import React, { useState, useMemo, useEffect, useRef } from 'react';
import { 
  Save, Trash2, Settings, FileText, Calculator, Volume2, 
  StopCircle, Loader2, User, Briefcase, Clock, Percent, 
  Table, Search, Filter, XCircle, Download, Eraser, Info
} from 'lucide-react';
import { GoogleGenAI, Modality } from "@google/genai";
import { WorkloadType, Config, CalculationEntry } from './types.ts';
import { 
  calculateFinalCoefficient, 
  calculateSupplement, 
  calculateDailyFte, 
  formatCurrency, 
  formatNumber 
} from './utils/calculations.ts';
import SettingsModal from './components/SettingsModal.tsx';
import DeleteConfirmationModal from './components/DeleteConfirmationModal.tsx';
import Tooltip from './components/Tooltip.tsx';

const STORAGE_KEY_ENTRIES = 'priemokos_entries_v2';
const STORAGE_KEY_CONFIG = 'priemokos_config_v2';

const App: React.FC = () => {
  const [config, setConfig] = useState<Config>(() => {
    try {
      const saved = localStorage.getItem(STORAGE_KEY_CONFIG);
      return saved ? JSON.parse(saved) : {
        bma: 1798.00,
        avgHours36: 150.6,
        avgHours40: 167.3
      };
    } catch {
      return { bma: 1798.00, avgHours36: 150.6, avgHours40: 167.3 };
    }
  });

  const [entries, setEntries] = useState<CalculationEntry[]>(() => {
    try {
      const saved = localStorage.getItem(STORAGE_KEY_ENTRIES);
      return saved ? JSON.parse(saved) : [];
    } catch {
      return [];
    }
  });

  const [isSettingsOpen, setIsSettingsOpen] = useState(false);
  const [deleteId, setDeleteId] = useState<string | null>(null);
  const [isPlayingAudio, setIsPlayingAudio] = useState(false);
  const [isGeneratingAudio, setIsGeneratingAudio] = useState(false);
  const audioContextRef = useRef<AudioContext | null>(null);
  const sourceNodeRef = useRef<AudioBufferSourceNode | null>(null);

  // Filtravimo būsena
  const [filterName, setFilterName] = useState('');
  const [filterPosition, setFilterPosition] = useState('');

  // Formos būsena
  const [position, setPosition] = useState('');
  const [fullName, setFullName] = useState('');
  const [workloadType, setWorkloadType] = useState<WorkloadType>(WorkloadType.H36);
  const [baseCoef, setBaseCoef] = useState<string>('1.0000');
  const [increasePercent, setIncreasePercent] = useState<string>('0');
  const [actualHours, setActualHours] = useState<string>('');
  const [workedDays, setWorkedDays] = useState<string>('1');
  const [errors, setErrors] = useState<Record<string, string>>({});

  useEffect(() => {
    localStorage.setItem(STORAGE_KEY_ENTRIES, JSON.stringify(entries));
    localStorage.setItem(STORAGE_KEY_CONFIG, JSON.stringify(config));
  }, [entries, config]);

  const parsedBaseCoef = parseFloat(baseCoef) || 0;
  const parsedIncrease = parseFloat(increasePercent) || 0;
  const parsedActualHours = parseFloat(actualHours) || 0;
  const parsedWorkedDays = parseFloat(workedDays) || 0;

  const avgMonthlyHours = workloadType === WorkloadType.H36 ? config.avgHours36 : config.avgHours40;
  const finalCoefficient = useMemo(() => calculateFinalCoefficient(parsedBaseCoef, parsedIncrease), [parsedBaseCoef, parsedIncrease]);
  const supplement = useMemo(() => calculateSupplement(finalCoefficient, config.bma, avgMonthlyHours, parsedActualHours), [finalCoefficient, config.bma, avgMonthlyHours, parsedActualHours]);
  const dailyFte = useMemo(() => calculateDailyFte(parsedActualHours, workloadType, parsedWorkedDays), [parsedActualHours, workloadType, parsedWorkedDays]);

  // Filtravimo logika
  const filteredEntries = useMemo(() => {
    return entries.filter(entry => {
      const matchesName = entry.fullName.toLowerCase().includes(filterName.toLowerCase());
      const matchesPosition = entry.position.toLowerCase().includes(filterPosition.toLowerCase());
      return matchesName && matchesPosition;
    });
  }, [entries, filterName, filterPosition]);

  const totalSupplement = useMemo(() => 
    filteredEntries.reduce((sum, e) => sum + e.salarySupplement, 0), 
    [filteredEntries]
  );

  const handleInputChange = (setter: (v: string) => void, field: string, value: string) => {
    setter(value);
    if (errors[field]) {
      const newErrors = { ...errors };
      delete newErrors[field];
      setErrors(newErrors);
    }
  };

  const resetForm = () => {
    setPosition('');
    setFullName('');
    setActualHours('');
    setWorkedDays('1');
    setErrors({});
  };

  const handleSave = () => {
    const newErrors: Record<string, string> = {};
    if (!position.trim()) newErrors.position = "Įveskite pareigas";
    if (!fullName.trim()) newErrors.fullName = "Įveskite vardą ir pavardę";
    if (!actualHours || parsedActualHours <= 0) newErrors.actualHours = "Įveskite valandas";

    if (Object.keys(newErrors).length > 0) {
      setErrors(newErrors);
      return;
    }

    const newEntry: CalculationEntry = {
      id: Date.now().toString(),
      position,
      fullName,
      workloadType,
      baseCoefficient: parsedBaseCoef,
      increasePercent: parsedIncrease,
      finalCoefficient,
      actualHours: parsedActualHours,
      workedDays: parsedWorkedDays > 0 ? parsedWorkedDays : undefined,
      salarySupplement: supplement,
      dailyFte,
      dateCreated: new Date().toISOString()
    };

    setEntries([newEntry, ...entries]);
    resetForm();
  };

  const confirmDelete = () => {
    if (deleteId) {
      setEntries(entries.filter(i => i.id !== deleteId));
      setDeleteId(null);
    }
  };

  const handleExportCsv = () => {
    if (filteredEntries.length === 0) return;

    const headers = [
      'Vardas Pavardė', 
      'Pareigos', 
      'Darbo rėžimas', 
      'Koeficientas', 
      'Faktinės valandos', 
      'Dirbtos dienos', 
      'Priemoka (EUR)', 
      'Etato dalis'
    ];

    const rows = filteredEntries.map(e => [
      `"${e.fullName}"`,
      `"${e.position}"`,
      e.workloadType === WorkloadType.H36 ? '36 val.' : '40 val.',
      formatNumber(e.finalCoefficient, 4).replace(',', '.'),
      formatNumber(e.actualHours, 1).replace(',', '.'),
      e.workedDays || '',
      formatNumber(e.salarySupplement, 2).replace(',', '.'),
      formatNumber(e.dailyFte, 2).replace(',', '.')
    ]);

    const csvContent = [
      headers.join(','),
      ...rows.map(row => row.join(','))
    ].join('\n');

    const blob = new Blob(['\ufeff' + csvContent], { type: 'text/csv;charset=utf-8;' });
    const url = URL.createObjectURL(blob);
    const link = document.createElement('a');
    link.setAttribute('href', url);
    link.setAttribute('download', `priemokos_eksportas_${new Date().toISOString().split('T')[0]}.csv`);
    document.body.appendChild(link);
    link.click();
    document.body.removeChild(link);
  };

  // Audio decoding following guidelines
  const decodeBase64 = (base64: string) => {
    const binaryString = atob(base64);
    const len = binaryString.length;
    const bytes = new Uint8Array(len);
    for (let i = 0; i < len; i++) {
      bytes[i] = binaryString.charCodeAt(i);
    }
    return bytes;
  };

  const decodeAudioData = async (
    data: Uint8Array,
    ctx: AudioContext,
    sampleRate: number,
    numChannels: number,
  ): Promise<AudioBuffer> => {
    const dataInt16 = new Int16Array(data.buffer);
    const frameCount = dataInt16.length / numChannels;
    const buffer = ctx.createBuffer(numChannels, frameCount, sampleRate);

    for (let channel = 0; channel < numChannels; channel++) {
      const channelData = buffer.getChannelData(channel);
      for (let i = 0; i < frameCount; i++) {
        channelData[i] = dataInt16[i * numChannels + channel] / 32768.0;
      }
    }
    return buffer;
  };

  const handleAudioGuide = async () => {
    if (isPlayingAudio) {
      sourceNodeRef.current?.stop();
      setIsPlayingAudio(false);
      return;
    }

    setIsGeneratingAudio(true);
    try {
      const ai = new GoogleGenAI({ apiKey: process.env.API_KEY });
      const promptText = `Sveiki! Ši skaičiuoklė padės jums greitai paskaičiuoti darbuotojų priemokas. Nepamirškite, kad užpildę duomenis, galite juos išsaugoti į istoriją, o vėliau visą sąrašą eksportuoti į Excel failą paspaudę mygtuką virš lentelės. Sėkmės darbuose!`;

      const response = await ai.models.generateContent({
        model: 'gemini-2.5-flash-preview-tts',
        contents: [{ parts: [{ text: promptText }] }],
        config: {
          responseModalities: [Modality.AUDIO],
          speechConfig: { 
            voiceConfig: { 
              prebuiltVoiceConfig: { voiceName: 'Kore' } 
            } 
          },
        },
      });

      const base64Audio = response.candidates?.[0]?.content?.parts?.[0]?.inlineData?.data;
      if (!base64Audio) return;

      if (!audioContextRef.current) {
        audioContextRef.current = new (window.AudioContext || (window as any).webkitAudioContext)({ sampleRate: 24000 });
      }

      const audioBuffer = await decodeAudioData(
        decodeBase64(base64Audio),
        audioContextRef.current,
        24000,
        1
      );

      const source = audioContextRef.current.createBufferSource();
      source.buffer = audioBuffer;
      source.connect(audioContextRef.current.destination);
      source.onended = () => setIsPlayingAudio(false);
      sourceNodeRef.current = source;
      source.start();
      setIsPlayingAudio(true);
    } catch (e) {
      console.error("Audio guide error:", e);
    } finally {
      setIsGeneratingAudio(false);
    }
  };

  const clearFilters = () => {
    setFilterName('');
    setFilterPosition('');
  };

  return (
    <div className="min-h-screen bg-slate-50 p-4 md:p-8">
      <header className="max-w-7xl mx-auto flex flex-col md:flex-row justify-between items-center mb-10 bg-white p-6 rounded-3xl shadow-sm border border-slate-100 gap-4">
        <div className="flex items-center gap-4">
          <div className="bg-indigo-600 p-3 rounded-2xl text-white shadow-indigo-100 shadow-xl">
            <Calculator size={28} />
          </div>
          <div>
            <h1 className="text-2xl font-extrabold text-slate-900 tracking-tight">Priemokų skaičiuoklė 2026</h1>
            <p className="text-xs font-bold text-slate-400 uppercase tracking-widest flex items-center gap-2">
              Bazinis dydis: {formatCurrency(config.bma)}
              <Tooltip text="BD nustatomas kasmet valstybės biudžete.">
                <Info size={12} className="cursor-help text-slate-300" />
              </Tooltip>
            </p>
          </div>
        </div>
        <div className="flex gap-3">
          <button 
            onClick={handleAudioGuide} 
            className={`flex items-center gap-2 px-4 py-2 rounded-2xl transition-all font-bold text-sm ${
              isPlayingAudio ? 'bg-red-50 text-red-600' : 'bg-slate-100 hover:bg-indigo-50 text-slate-600 hover:text-indigo-600'
            }`}
          >
            {isGeneratingAudio ? (
              <Loader2 size={20} className="animate-spin" />
            ) : isPlayingAudio ? (
              <><StopCircle size={20} /> Sustabdyti</>
            ) : (
              <><Volume2 size={20} /> Garsinis gidas</>
            )}
          </button>
          <button 
            onClick={() => setIsSettingsOpen(true)} 
            className="p-3 bg-slate-100 hover:bg-slate-200 text-slate-600 rounded-2xl transition-all"
            title="Nustatymai"
          >
            <Settings size={20} />
          </button>
        </div>
      </header>

      <main className="max-w-7xl mx-auto grid grid-cols-1 lg:grid-cols-12 gap-8">
        {/* Formos skiltis */}
        <section className="lg:col-span-5 space-y-6">
          <div className="bg-white p-8 rounded-[2rem] shadow-xl shadow-slate-200/50 border border-slate-100">
            <div className="flex justify-between items-center mb-6">
              <h2 className="text-lg font-bold text-slate-800 flex items-center gap-2">
                <FileText size={20} className="text-indigo-600" /> Duomenų įvedimas
              </h2>
              <button 
                onClick={resetForm}
                className="text-[10px] font-black uppercase text-slate-400 hover:text-red-500 transition-colors flex items-center gap-1"
              >
                <Eraser size={12} /> Išvalyti
              </button>
            </div>

            <div className="space-y-5">
              <div className="space-y-1.5">
                <label className="text-xs font-bold text-slate-500 uppercase ml-1">Pareigos</label>
                <div className="relative">
                  <Briefcase className="absolute left-4 top-1/2 -translate-y-1/2 text-slate-400" size={18} />
                  <input 
                    type="text" 
                    value={position} 
                    onChange={e => handleInputChange(setPosition, 'position', e.target.value)} 
                    placeholder="Pvz.: Vyriausiasis specialistas" 
                    className={`w-full pl-12 pr-4 py-3 bg-slate-50 border rounded-2xl outline-none focus:ring-4 transition-all ${
                      errors.position ? 'border-red-200 focus:ring-red-50' : 'border-slate-100 focus:ring-indigo-50'
                    }`} 
                  />
                </div>
                {errors.position && <p className="text-[10px] text-red-500 font-bold ml-1 uppercase">{errors.position}</p>}
              </div>

              <div className="space-y-1.5">
                <label className="text-xs font-bold text-slate-500 uppercase ml-1">Vardas, Pavardė</label>
                <div className="relative">
                  <User className="absolute left-4 top-1/2 -translate-y-1/2 text-slate-400" size={18} />
                  <input 
                    type="text" 
                    value={fullName} 
                    onChange={e => handleInputChange(setFullName, 'fullName', e.target.value)} 
                    placeholder="Vardas Pavardė" 
                    className={`w-full pl-12 pr-4 py-3 bg-slate-50 border rounded-2xl outline-none focus:ring-4 transition-all ${
                      errors.fullName ? 'border-red-200 focus:ring-red-50' : 'border-slate-100 focus:ring-indigo-50'
                    }`} 
                  />
                </div>
                {errors.fullName && <p className="text-[10px] text-red-500 font-bold ml-1 uppercase">{errors.fullName}</p>}
              </div>

              <div className="space-y-1.5">
                <label className="text-xs font-bold text-slate-500 uppercase ml-1">Savaitės norma (rėžimas)</label>
                <div className="grid grid-cols-2 gap-3">
                  <button 
                    onClick={() => setWorkloadType(WorkloadType.H36)} 
                    className={`py-3 rounded-2xl border-2 transition-all font-bold text-sm ${
                      workloadType === WorkloadType.H36 ? 'border-indigo-600 bg-indigo-50 text-indigo-700' : 'border-slate-50 bg-slate-50 text-slate-400'
                    }`}
                  >
                    36 val. / sav.
                  </button>
                  <button 
                    onClick={() => setWorkloadType(WorkloadType.H40)} 
                    className={`py-3 rounded-2xl border-2 transition-all font-bold text-sm ${
                      workloadType === WorkloadType.H40 ? 'border-indigo-600 bg-indigo-50 text-indigo-700' : 'border-slate-50 bg-slate-50 text-slate-400'
                    }`}
                  >
                    40 val. / sav.
                  </button>
                </div>
              </div>

              <div className="grid grid-cols-2 gap-4">
                <div className="space-y-1.5">
                  <label className="text-xs font-bold text-slate-500 uppercase ml-1">Koeficientas</label>
                  <input 
                    type="number" 
                    step="0.0001" 
                    value={baseCoef} 
                    onChange={e => setBaseCoef(e.target.value)} 
                    className="w-full p-3 bg-slate-50 border border-slate-100 rounded-2xl font-mono font-bold focus:ring-2 focus:ring-indigo-50 outline-none" 
                  />
                </div>
                <div className="space-y-1.5">
                  <label className="text-xs font-bold text-slate-500 uppercase ml-1">Didinimas (%)</label>
                  <div className="relative">
                    <input 
                      type="number" 
                      value={increasePercent} 
                      onChange={e => setIncreasePercent(e.target.value)} 
                      className="w-full p-3 bg-slate-50 border border-slate-100 rounded-2xl font-mono font-bold focus:ring-2 focus:ring-indigo-50 outline-none" 
                    />
                    <Percent size={14} className="absolute right-4 top-1/2 -translate-y-1/2 text-slate-400" />
                  </div>
                </div>
              </div>

              <div className="grid grid-cols-2 gap-4">
                <div className="space-y-1.5">
                  <label className="text-xs font-bold text-slate-500 uppercase ml-1">Dirbtos valandos</label>
                  <div className="relative">
                    <Clock className="absolute left-4 top-1/2 -translate-y-1/2 text-slate-400" size={18} />
                    <input 
                      type="number" 
                      step="0.5" 
                      value={actualHours} 
                      onChange={e => handleInputChange(setActualHours, 'actualHours', e.target.value)} 
                      placeholder="Pvz. 150"
                      className={`w-full pl-12 pr-4 py-3 bg-slate-50 border rounded-2xl outline-none focus:ring-4 transition-all ${
                        errors.actualHours ? 'border-red-200 focus:ring-red-50' : 'border-slate-100 focus:ring-indigo-50'
                      }`} 
                    />
                  </div>
                </div>
                <div className="space-y-1.5">
                  <label className="text-xs font-bold text-slate-500 uppercase ml-1 flex items-center gap-1">
                    Dirbtos dienos
                    <Tooltip text="Reikalinga tikslesniam etato dalies paskaičiavimui.">
                      <Info size={10} />
                    </Tooltip>
                  </label>
                  <input 
                    type="number" 
                    value={workedDays} 
                    onChange={e => setWorkedDays(e.target.value)} 
                    placeholder="pvz. 1" 
                    className="w-full p-3 bg-slate-50 border border-slate-100 rounded-2xl font-bold focus:ring-2 focus:ring-indigo-50 outline-none" 
                  />
                </div>
              </div>

              <button 
                onClick={handleSave} 
                className="w-full py-4 bg-indigo-600 hover:bg-indigo-700 text-white rounded-2xl font-bold shadow-lg shadow-indigo-100 flex items-center justify-center gap-2 transition-all transform active:scale-[0.98]"
              >
                <Save size={20} /> Išsaugoti įrašą
              </button>
            </div>
          </div>
        </section>

        {/* Rezultatų ir Istorijos skiltis */}
        <section className="lg:col-span-7 space-y-6">
          <div className="grid grid-cols-1 md:grid-cols-2 gap-6">
            <div className="bg-sheet-orange p-8 rounded-[2rem] border border-orange-300 shadow-xl shadow-orange-100 flex flex-col items-center justify-center text-center group hover:scale-[1.02] transition-transform">
              <span className="text-xs font-black uppercase tracking-widest text-orange-900/40 mb-2">Paskaičiuota priemoka (Bruto)</span>
              <span className="text-5xl font-black text-slate-900">{formatCurrency(supplement)}</span>
            </div>
            <div className="bg-sheet-cyan p-8 rounded-[2rem] border border-cyan-300 shadow-xl shadow-cyan-100 flex flex-col items-center justify-center text-center group hover:scale-[1.02] transition-transform">
              <span className="text-xs font-black uppercase tracking-widest text-cyan-900/40 mb-2">Etato dalis per dieną</span>
              <span className="text-5xl font-black text-slate-900">{formatNumber(dailyFte, 2)}</span>
            </div>
          </div>

          <div className="bg-white rounded-[2rem] shadow-xl shadow-slate-200/50 border border-slate-100 overflow-hidden">
            <div className="px-8 py-5 border-b border-slate-50 flex flex-col gap-4">
              <div className="flex items-center justify-between flex-wrap gap-4">
                <div className="flex items-center gap-4">
                  <h3 className="font-bold text-slate-800 flex items-center gap-2">
                    <Table size={20} className="text-indigo-600" /> Istorija
                  </h3>
                  <button 
                    onClick={handleExportCsv}
                    disabled={filteredEntries.length === 0}
                    className="flex items-center gap-1.5 px-3 py-1.5 bg-white border border-indigo-200 text-indigo-600 hover:bg-indigo-50 rounded-xl text-xs font-bold transition-all disabled:opacity-50 disabled:cursor-not-allowed"
                  >
                    <Download size={14} /> Eksportuoti CSV
                  </button>
                </div>

                {/* Filtravimo juosta */}
                <div className="flex items-center gap-3 flex-grow md:justify-end">
                  <div className="relative max-w-[150px] w-full">
                     <Search className="absolute left-3 top-1/2 -translate-y-1/2 text-slate-400" size={14} />
                     <input 
                      type="text" 
                      placeholder="Vardas..." 
                      value={filterName}
                      onChange={(e) => setFilterName(e.target.value)}
                      className="w-full pl-9 pr-3 py-1.5 bg-slate-50 border border-slate-100 rounded-xl text-xs outline-none focus:ring-2 focus:ring-indigo-100 transition-all" 
                     />
                  </div>
                  <div className="relative max-w-[150px] w-full">
                     <Filter className="absolute left-3 top-1/2 -translate-y-1/2 text-slate-400" size={14} />
                     <input 
                      type="text" 
                      placeholder="Pareigos..." 
                      value={filterPosition}
                      onChange={(e) => setFilterPosition(e.target.value)}
                      className="w-full pl-9 pr-3 py-1.5 bg-slate-50 border border-slate-100 rounded-xl text-xs outline-none focus:ring-2 focus:ring-indigo-100 transition-all" 
                     />
                  </div>
                  {(filterName || filterPosition) && (
                    <button 
                      onClick={clearFilters}
                      className="p-1.5 text-slate-400 hover:text-red-500 transition-colors"
                      title="Išvalyti filtrus"
                    >
                      <XCircle size={18} />
                    </button>
                  )}
                </div>
              </div>

              {/* Suvestinė po filtrais */}
              <div className="flex items-center justify-between bg-slate-50 p-3 rounded-2xl border border-slate-100">
                <span className="text-[10px] font-bold text-slate-500 uppercase tracking-widest">
                  Rodomi {filteredEntries.length} iš {entries.length} įrašų
                </span>
                <span className="text-[10px] font-bold text-slate-500 uppercase tracking-widest">
                  Bendra suma: <span className="text-indigo-600 ml-1">{formatCurrency(totalSupplement)}</span>
                </span>
              </div>
            </div>

            <div className="max-h-[500px] overflow-y-auto">
              <table className="w-full text-left">
                <thead className="bg-slate-50/50 text-[10px] font-bold text-slate-400 uppercase tracking-wider sticky top-0 backdrop-blur-md z-10">
                  <tr>
                    <th className="px-8 py-4">Darbuotojas</th>
                    <th className="px-2 py-4 text-right">Val.</th>
                    <th className="px-2 py-4 text-right">Etato d.</th>
                    <th className="px-4 py-4 text-right">Priemoka</th>
                    <th className="px-8 py-4"></th>
                  </tr>
                </thead>
                <tbody className="divide-y divide-slate-50">
                  {filteredEntries.map(e => (
                    <tr key={e.id} className="group hover:bg-slate-50/80 transition-colors">
                      <td className="px-8 py-4">
                        <div className="font-bold text-slate-800 text-sm">{e.fullName}</div>
                        <div className="text-[10px] font-bold text-slate-400 uppercase tracking-tight">{e.position}</div>
                      </td>
                      <td className="px-2 py-4 text-right font-mono text-xs font-bold text-slate-600">
                        {formatNumber(e.actualHours, 1)}
                      </td>
                      <td className="px-2 py-4 text-right font-mono text-xs font-bold text-cyan-600">
                        {formatNumber(e.dailyFte, 2)}
                      </td>
                      <td className="px-4 py-4 text-right">
                        <span className="bg-orange-100 text-orange-700 px-3 py-1 rounded-full font-extrabold text-xs">
                          {formatCurrency(e.salarySupplement)}
                        </span>
                      </td>
                      <td className="px-8 py-4 text-right">
                        <button 
                          onClick={() => setDeleteId(e.id)} 
                          className="p-2 text-slate-300 hover:text-red-500 hover:bg-red-50 rounded-xl transition-all"
                          title="Ištrinti"
                        >
                          <Trash2 size={16} />
                        </button>
                      </td>
                    </tr>
                  ))}
                  {filteredEntries.length === 0 && (
                    <tr>
                      <td colSpan={5} className="px-8 py-16 text-center text-slate-400 italic text-sm">
                        {entries.length === 0 
                          ? "Istorija tuščia. Užpildykite formą kairėje." 
                          : "Nerasta įrašų pagal pasirinktus filtrus."}
                      </td>
                    </tr>
                  )}
                </tbody>
              </table>
            </div>
          </div>
        </section>
      </main>

      <SettingsModal 
        isOpen={isSettingsOpen} 
        onClose={() => setIsSettingsOpen(false)} 
        config={config} 
        onSave={setConfig} 
        onClearData={() => {
          setEntries([]);
          localStorage.removeItem(STORAGE_KEY_ENTRIES);
        }} 
      />

      <DeleteConfirmationModal 
        isOpen={!!deleteId}
        onClose={() => setDeleteId(null)}
        onConfirm={confirmDelete}
      />
    </div>
  );
};

