import React, { useState, useMemo, useEffect, useRef } from 'react';
import { 
  Save, Trash2, Settings, FileText, Calculator, Volume2, 
  StopCircle, Loader2, User, Briefcase, Clock, Percent, 
  Table, Search, Filter, XCircle, Download, Eraser, Info,
  ChevronRight, CheckCircle2
} from 'lucide-react';
import { GoogleGenAI, Modality } from "@google/genai";
import { WorkloadType, Config, CalculationEntry } from './types.ts';
import { 
  calculateFinalCoefficient, 
  calculateSupplement, 
  calculateDailyFte, 
  formatCurrency, 
  formatNumber 
} from './utils/calculations.ts';
import SettingsModal from './components/SettingsModal.tsx';
import DeleteConfirmationModal from './components/DeleteConfirmationModal.tsx';
import Tooltip from './components/Tooltip.tsx';

const STORAGE_KEY_ENTRIES = 'priemokos_entries_v2';
const STORAGE_KEY_CONFIG = 'priemokos_config_v2';

const App: React.FC = () => {
  const [config, setConfig] = useState<Config>(() => {
    try {
      const saved = localStorage.getItem(STORAGE_KEY_CONFIG);
      return saved ? JSON.parse(saved) : {
        bma: 1798.00,
        avgHours36: 150.6,
        avgHours40: 167.3
      };
    } catch {
      return { bma: 1798.00, avgHours36: 150.6, avgHours40: 167.3 };
    }
  });

  const [entries, setEntries] = useState<CalculationEntry[]>(() => {
    try {
      const saved = localStorage.getItem(STORAGE_KEY_ENTRIES);
      return saved ? JSON.parse(saved) : [];
    } catch {
      return [];
    }
  });

  const [isSettingsOpen, setIsSettingsOpen] = useState(false);
  const [deleteId, setDeleteId] = useState<string | null>(null);
  const [isPlayingAudio, setIsPlayingAudio] = useState(false);
  const [isGeneratingAudio, setIsGeneratingAudio] = useState(false);
  const audioContextRef = useRef<AudioContext | null>(null);
  const sourceNodeRef = useRef<AudioBufferSourceNode | null>(null);

  const [filterName, setFilterName] = useState('');
  const [filterPosition, setFilterPosition] = useState('');

  const [position, setPosition] = useState('');
  const [fullName, setFullName] = useState('');
  const [workloadType, setWorkloadType] = useState<WorkloadType>(WorkloadType.H36);
  const [baseCoef, setBaseCoef] = useState<string>('1.0000');
  const [increasePercent, setIncreasePercent] = useState<string>('0');
  const [actualHours, setActualHours] = useState<string>('');
  const [workedDays, setWorkedDays] = useState<string>('1');
  const [errors, setErrors] = useState<Record<string, string>>({});

  useEffect(() => {
    localStorage.setItem(STORAGE_KEY_ENTRIES, JSON.stringify(entries));
    localStorage.setItem(STORAGE_KEY_CONFIG, JSON.stringify(config));
  }, [entries, config]);

  const parsedBaseCoef = parseFloat(baseCoef) || 0;
  const parsedIncrease = parseFloat(increasePercent) || 0;
  const parsedActualHours = parseFloat(actualHours) || 0;
  const parsedWorkedDays = parseFloat(workedDays) || 0;

  const avgMonthlyHours = workloadType === WorkloadType.H36 ? config.avgHours36 : config.avgHours40;
  const finalCoefficient = useMemo(() => calculateFinalCoefficient(parsedBaseCoef, parsedIncrease), [parsedBaseCoef, parsedIncrease]);
  const supplement = useMemo(() => calculateSupplement(finalCoefficient, config.bma, avgMonthlyHours, parsedActualHours), [finalCoefficient, config.bma, avgMonthlyHours, parsedActualHours]);
  const dailyFte = useMemo(() => calculateDailyFte(parsedActualHours, workloadType, parsedWorkedDays), [parsedActualHours, workloadType, parsedWorkedDays]);

  const filteredEntries = useMemo(() => {
    return entries.filter(entry => {
      const matchesName = entry.fullName.toLowerCase().includes(filterName.toLowerCase());
      const matchesPosition = entry.position.toLowerCase().includes(filterPosition.toLowerCase());
      return matchesName && matchesPosition;
    });
  }, [entries, filterName, filterPosition]);

  const totalSupplement = useMemo(() => 
    filteredEntries.reduce((sum, e) => sum + e.salarySupplement, 0), 
    [filteredEntries]
  );

  const handleInputChange = (setter: (v: string) => void, field: string, value: string) => {
    setter(value);
    if (errors[field]) {
      const newErrors = { ...errors };
      delete newErrors[field];
      setErrors(newErrors);
    }
  };

  const resetForm = () => {
    setPosition('');
    setFullName('');
    setActualHours('');
    setWorkedDays('1');
    setErrors({});
  };

  const handleSave = () => {
    const newErrors: Record<string, string> = {};
    if (!position.trim()) newErrors.position = "Įveskite pareigas";
    if (!fullName.trim()) newErrors.fullName = "Įveskite vardą ir pavardę";
    if (!actualHours || parsedActualHours <= 0) newErrors.actualHours = "Įveskite valandas";

    if (Object.keys(newErrors).length > 0) {
      setErrors(newErrors);
      return;
    }

    const newEntry: CalculationEntry = {
      id: Date.now().toString(),
      position,
      fullName,
      workloadType,
      baseCoefficient: parsedBaseCoef,
      increasePercent: parsedIncrease,
      finalCoefficient,
      actualHours: parsedActualHours,
      workedDays: parsedWorkedDays > 0 ? parsedWorkedDays : undefined,
      salarySupplement: supplement,
      dailyFte,
      dateCreated: new Date().toISOString()
    };

    setEntries([newEntry, ...entries]);
    resetForm();
  };

  const confirmDelete = () => {
    if (deleteId) {
      setEntries(entries.filter(i => i.id !== deleteId));
      setDeleteId(null);
    }
  };

  const handleExportCsv = () => {
    if (filteredEntries.length === 0) return;

    const headers = [
      'Vardas Pavardė', 
      'Pareigos',
      'Darbo rėžimas',
      'Galutinis koef.',
      'Faktinės valandos',
      'Priemoka (EUR)',
      'Etato dalis'
    ];

    const rows = filteredEntries.map(e => [
      `"${e.fullName}"`,
      `"${e.position}"`,
      e.workloadType === WorkloadType.H36 ? '36 val.' : '40 val.',
      formatNumber(e.finalCoefficient, 4).replace(',', '.'),
      formatNumber(e.actualHours, 1).replace(',', '.'),
      formatNumber(e.salarySupplement, 2).replace(',', '.'),
      formatNumber(e.dailyFte, 2).replace(',', '.')
    ]);

    const csvContent = [
      headers.join(','),
      ...rows.map(row => row.join(','))
    ].join('\n');

    const blob = new Blob(['\ufeff' + csvContent], { type: 'text/csv;charset=utf-8;' });
    const url = URL.createObjectURL(blob);
    const link = document.createElement('a');
    link.setAttribute('href', url);
    link.setAttribute('download', `priemokos_${new Date().toISOString().split('T')[0]}.csv`);
    document.body.appendChild(link);
    link.click();
    document.body.removeChild(link);
  };

  const decodeBase64 = (base64: string) => {
    const binaryString = atob(base64);
    const bytes = new Uint8Array(binaryString.length);
    for (let i = 0; i < binaryString.length; i++) {
      bytes[i] = binaryString.charCodeAt(i);
    }
    return bytes;
  };

  const decodeAudioData = async (data: Uint8Array, ctx: AudioContext, sampleRate: number, numChannels: number): Promise<AudioBuffer> => {
    const dataInt16 = new Int16Array(data.buffer);
    const frameCount = dataInt16.length / numChannels;
    const buffer = ctx.createBuffer(numChannels, frameCount, sampleRate);
    for (let channel = 0; channel < numChannels; channel++) {
      const channelData = buffer.getChannelData(channel);
      for (let i = 0; i < frameCount; i++) {
        channelData[i] = dataInt16[i * numChannels + channel] / 32768.0;
      }
    }
    return buffer;
  };

  const handleAudioGuide = async () => {
    if (isPlayingAudio) {
      sourceNodeRef.current?.stop();
      setIsPlayingAudio(false);
      return;
    }
    setIsGeneratingAudio(true);
    try {
      const ai = new GoogleGenAI({ apiKey: process.env.API_KEY });
      const prompt = "Sveiki atvykę į priemokų skaičiuoklę. Įveskite darbuotojo pareigas, vardą ir dirbtas valandas. Sistema automatiškai paskaičiuos sumą pagal patvirtintą bazinį dydį.";
      const response = await ai.models.generateContent({
        model: 'gemini-2.5-flash-preview-tts',
        contents: [{ parts: [{ text: prompt }] }],
        config: {
          responseModalities: [Modality.AUDIO],
          speechConfig: { voiceConfig: { prebuiltVoiceConfig: { voiceName: 'Kore' } } },
        },
      });
      const base64Audio = response.candidates?.[0]?.content?.parts?.[0]?.inlineData?.data;
      if (!base64Audio) return;
      if (!audioContextRef.current) audioContextRef.current = new (window.AudioContext || (window as any).webkitAudioContext)({ sampleRate: 24000 });
      const audioBuffer = await decodeAudioData(decodeBase64(base64Audio), audioContextRef.current, 24000, 1);
      const source = audioContextRef.current.createBufferSource();
      source.buffer = audioBuffer;
      source.connect(audioContextRef.current.destination);
      source.onended = () => setIsPlayingAudio(false);
      sourceNodeRef.current = source;
      source.start();
      setIsPlayingAudio(true);
    } catch (e) { console.error(e); } finally { setIsGeneratingAudio(false); }
  };

  return (
    <div className="min-h-screen bg-slate-50 p-4 md:p-8">
      <header className="max-w-7xl mx-auto flex flex-col md:flex-row justify-between items-center mb-10 bg-white p-6 rounded-3xl shadow-sm border border-slate-100 gap-4">
        <div className="flex items-center gap-4">
          <div className="bg-indigo-600 p-3 rounded-2xl text-white shadow-xl">
            <Calculator size={28} />
          </div>
          <div>
            <h1 className="text-2xl font-extrabold text-slate-900">Priemokų skaičiuoklė 2026</h1>
            <p className="text-xs font-bold text-slate-400 uppercase tracking-widest">BD: {formatCurrency(config.bma)}</p>
          </div>
        </div>
        <div className="flex gap-3">
          <button onClick={handleAudioGuide} className={`flex items-center gap-2 px-4 py-2 rounded-2xl transition-all font-bold text-sm ${isPlayingAudio ? 'bg-red-50 text-red-600' : 'bg-slate-100 text-slate-600'}`}>
            {isGeneratingAudio ? <Loader2 size={20} className="animate-spin" /> : isPlayingAudio ? <><StopCircle size={20} /> Stop</> : <><Volume2 size={20} /> Gidas</>}
          </button>
          <button onClick={() => setIsSettingsOpen(true)} className="p-3 bg-slate-100 text-slate-600 rounded-2xl"><Settings size={20} /></button>
        </div>
      </header>

      <main className="max-w-7xl mx-auto grid grid-cols-1 lg:grid-cols-12 gap-8">
        <section className="lg:col-span-5 space-y-6">
          <div className="bg-white p-8 rounded-[2rem] shadow-xl border border-slate-100">
            <h2 className="text-lg font-bold text-slate-800 mb-6 flex items-center gap-2"><FileText size={20} className="text-indigo-600" /> Duomenys</h2>
            <div className="space-y-5">
              <div className="space-y-1.5">
                <label className="text-xs font-bold text-slate-500 uppercase">1. Pareigos</label>
                <div className="relative">
                  <Briefcase className="absolute left-4 top-1/2 -translate-y-1/2 text-slate-400" size={18} />
                  <input type="text" value={position} onChange={e => handleInputChange(setPosition, 'position', e.target.value)} placeholder="Pareigos" className="w-full pl-12 pr-4 py-3 bg-slate-50 border rounded-2xl outline-none focus:ring-4 focus:ring-indigo-50" />
                </div>
                {errors.position && <p className="text-[10px] text-red-500 font-bold uppercase">{errors.position}</p>}
              </div>
              <div className="space-y-1.5">
                <label className="text-xs font-bold text-slate-500 uppercase">2. Vardas, Pavardė</label>
                <div className="relative">
                  <User className="absolute left-4 top-1/2 -translate-y-1/2 text-slate-400" size={18} />
                  <input type="text" value={fullName} onChange={e => handleInputChange(setFullName, 'fullName', e.target.value)} placeholder="Vardas Pavardė" className="w-full pl-12 pr-4 py-3 bg-slate-50 border rounded-2xl outline-none focus:ring-4 focus:ring-indigo-50" />
                </div>
                {errors.fullName && <p className="text-[10px] text-red-500 font-bold uppercase">{errors.fullName}</p>}
              </div>
              <div className="space-y-1.5">
                <label className="text-xs font-bold text-slate-500 uppercase">3. Savaitės norma</label>
                <div className="grid grid-cols-2 gap-3">
                  {[WorkloadType.H36, WorkloadType.H40].map(t => (
                    <button key={t} onClick={() => setWorkloadType(t)} className={`py-3 rounded-2xl border-2 font-bold text-sm transition-all ${workloadType === t ? 'border-indigo-600 bg-indigo-50 text-indigo-700' : 'border-slate-50 bg-slate-50 text-slate-400'}`}>
                      {t === WorkloadType.H36 ? '36 val.' : '40 val.'}
                    </button>
                  ))}
                </div>
              </div>
              <div className="grid grid-cols-2 gap-4">
                <div className="space-y-1.5">
                  <label className="text-xs font-bold text-slate-500 uppercase">Koeficientas</label>
                  <input type="number" step="0.0001" value={baseCoef} onChange={e => setBaseCoef(e.target.value)} className="w-full p-3 bg-slate-50 border border-slate-100 rounded-2xl font-mono font-bold" />
                </div>
                <div className="space-y-1.5">
                  <label className="text-xs font-bold text-slate-500 uppercase">Valandos</label>
                  <input type="number" value={actualHours} onChange={e => handleInputChange(setActualHours, 'actualHours', e.target.value)} placeholder="0" className="w-full p-3 bg-slate-50 border border-slate-100 rounded-2xl font-bold" />
                </div>
              </div>
              <button onClick={handleSave} className="w-full py-4 bg-indigo-600 text-white rounded-2xl font-bold shadow-lg hover:bg-indigo-700 transition-all flex items-center justify-center gap-2"><Save size={20} /> Išsaugoti</button>
            </div>
          </div>
        </section>

        <section className="lg:col-span-7 space-y-6">
          <div className="grid grid-cols-1 md:grid-cols-2 gap-6">
            <div className="bg-sheet-orange/10 p-8 rounded-[2rem] border border-orange-200 text-center">
              <span className="text-xs font-black uppercase text-orange-900/40 block mb-2">Priemoka</span>
              <span className="text-4xl font-black text-slate-900">{formatCurrency(supplement)}</span>
            </div>
            <div className="bg-sheet-cyan/10 p-8 rounded-[2rem] border border-cyan-200 text-center">
              <span className="text-xs font-black uppercase text-cyan-900/40 block mb-2">Etato dalis</span>
              <span className="text-4xl font-black text-slate-900">{formatNumber(dailyFte, 2)}</span>
            </div>
          </div>

          <div className="bg-white rounded-[2rem] shadow-xl border border-slate-100 overflow-hidden">
            <div className="p-6 border-b flex justify-between items-center bg-slate-50/50">
              <h3 className="font-bold text-slate-800 flex items-center gap-2"><Table size={20} /> Istorija</h3>
              <button onClick={handleExportCsv} className="flex items-center gap-2 text-xs font-bold text-indigo-600 bg-white px-4 py-2 rounded-xl border border-indigo-100 hover:bg-indigo-50 transition-all"><Download size={16} /> CSV</button>
            </div>
            <div className="overflow-x-auto">
              <table className="w-full">
                <thead className="bg-slate-50 text-[10px] font-bold text-slate-400 uppercase">
                  <tr>
                    <th className="px-6 py-4 text-left">Darbuotojas</th>
                    <th className="px-6 py-4 text-right">Val.</th>
                    <th className="px-6 py-4 text-right">Suma</th>
                    <th className="px-6 py-4"></th>
                  </tr>
                </thead>
                <tbody className="divide-y">
                  {filteredEntries.map(e => (
                    <tr key={e.id} className="hover:bg-slate-50/50 transition-colors">
                      <td className="px-6 py-4 text-sm font-bold text-slate-700">{e.fullName}<br/><span className="text-[10px] font-normal text-slate-400 uppercase">{e.position}</span></td>
                      <td className="px-6 py-4 text-right font-mono text-sm">{e.actualHours}</td>
                      <td className="px-6 py-4 text-right"><span className="bg-indigo-50 text-indigo-700 px-3 py-1 rounded-full font-bold text-xs">{formatCurrency(e.salarySupplement)}</span></td>
                      <td className="px-6 py-4 text-right"><button onClick={() => setDeleteId(e.id)} className="text-slate-300 hover:text-red-500"><Trash2 size={16}/></button></td>
                    </tr>
                  ))}
                </tbody>
              </table>
            </div>
          </div>
        </section>
      </main>

      <SettingsModal isOpen={isSettingsOpen} onClose={() => setIsSettingsOpen(false)} config={config} onSave={setConfig} onClearData={() => setEntries([])} />
      <DeleteConfirmationModal isOpen={!!deleteId} onClose={() => setDeleteId(null)} onConfirm={confirmDelete} />
    </div>
  );
};

