                    className={`w-full pl-12 pr-4 py-3 bg-slate-50 border rounded-2xl outline-none transition-all focus:ring-4 ${errors.position ? 'border-red-300 focus:ring-red-50' : 'border-slate-100 focus:ring-indigo-50'}`} 
                  />
                  <datalist id="positions-list">
                    {uniquePositions.map(p => <option key={p} value={p} />)}
                  </datalist>
                </div>
                {errors.position && <p className="text-[10px] text-red-500 font-bold uppercase ml-1">{errors.position}</p>}
              </div>

              {/* Vardas Pavardė */}
              <div className="space-y-1.5">
                <label className="text-xs font-bold text-slate-500 uppercase ml-1">2. Vardas, Pavardė</label>
                <div className="relative">
                  <User className="absolute left-4 top-1/2 -translate-y-1/2 text-slate-400" size={18} />
                  <input 
                    type="text" 
                    value={fullName} 
                    onChange={e => handleInputChange(setFullName, 'fullName', e.target.value)} 
                    placeholder="Vardas Pavardė" 
                    className={`w-full pl-12 pr-4 py-3 bg-slate-50 border rounded-2xl outline-none transition-all focus:ring-4 ${errors.fullName ? 'border-red-300 focus:ring-red-50' : 'border-slate-100 focus:ring-indigo-50'}`} 
                  />
                </div>
                {errors.fullName && <p className="text-[10px] text-red-500 font-bold uppercase ml-1">{errors.fullName}</p>}
              </div>

              {/* Darbo rėžimas */}
              <div className="space-y-1.5">
                <label className="text-xs font-bold text-slate-500 uppercase ml-1">3. Savaitės norma</label>
                <div className="grid grid-cols-2 gap-3">
                  {[WorkloadType.H36, WorkloadType.H40].map(t => (
                    <button key={t} onClick={() => setWorkloadType(t)} className={`py-3 rounded-2xl border-2 font-bold text-sm transition-all ${workloadType === t ? 'border-indigo-600 bg-indigo-50 text-indigo-700' : 'border-slate-50 bg-slate-50 text-slate-400'}`}>
                      {t === WorkloadType.H36 ? '36 val.' : '40 val.'}
                    </button>
                  ))}
                </div>
              </div>

              {/* Koeficientas ir valandos */}
              <div className="grid grid-cols-2 gap-4">
                <div className="space-y-1.5">
                  <label className="text-xs font-bold text-slate-500 uppercase ml-1">Koeficientas</label>
                  <input type="number" step="0.0001" value={baseCoef} onChange={e => setBaseCoef(e.target.value)} className="w-full p-3 bg-slate-50 border border-slate-100 rounded-2xl font-mono font-bold outline-none focus:ring-2 focus:ring-indigo-50" />
                </div>
                <div className="space-y-1.5">
                  <label className="text-xs font-bold text-slate-500 uppercase ml-1">Fakt. valandos</label>
                  <div className="relative">
                    <Clock className="absolute left-3 top-1/2 -translate-y-1/2 text-slate-400" size={16} />
                    <input type="number" step="0.1" value={actualHours} onChange={e => handleInputChange(setActualHours, 'actualHours', e.target.value)} placeholder="0" className={`w-full pl-9 pr-3 py-3 bg-slate-50 border rounded-2xl font-bold outline-none transition-all focus:ring-4 ${errors.actualHours ? 'border-red-300 focus:ring-red-50' : 'border-slate-100 focus:ring-indigo-50'}`} />
                  </div>
                </div>
              </div>

              {/* Dirbtos dienos - svarbu etato skaičiavimui */}
              <div className="space-y-1.5">
                <label className="text-xs font-bold text-slate-500 uppercase ml-1 flex items-center gap-1">
                  <CalendarDays size={14} className="text-indigo-600" /> 4. Dirbtos dienos per mėnesį
                  <Tooltip text="Svarbu tiksliam vidutiniam dienos etatui paskaičiuoti.">
                    <Info size={12} className="text-slate-300" />
                  </Tooltip>
                </label>
                <input 
                  type="number" 
                  value={workedDays} 
                  onChange={e => handleInputChange(setWorkedDays, 'workedDays', e.target.value)} 
                  className={`w-full p-3 bg-indigo-50/30 border rounded-2xl font-bold outline-none transition-all focus:ring-4 ${errors.workedDays ? 'border-red-300 focus:ring-red-50' : 'border-indigo-100 focus:ring-indigo-100'}`} 
                />
                {errors.workedDays && <p className="text-[10px] text-red-500 font-bold uppercase ml-1">{errors.workedDays}</p>}
              </div>

              <button onClick={handleSave} className="w-full py-4 bg-indigo-600 text-white rounded-2xl font-bold shadow-lg shadow-indigo-100 hover:bg-indigo-700 transition-all transform active:scale-[0.98] flex items-center justify-center gap-2">
                <Save size={20} /> Išsaugoti įrašą
              </button>
            </div>
          </div>
        </section>

        {/* Rezultatai ir Lentelė */}
        <section className="lg:col-span-7 space-y-6">
          <div className="grid grid-cols-1 md:grid-cols-2 gap-6">
            <div className="bg-sheet-orange/10 p-8 rounded-[2rem] border border-orange-200 shadow-sm text-center">
              <span className="text-xs font-black uppercase text-orange-900/40 block mb-2 tracking-widest">Paskaičiuota priemoka</span>
              <span className="text-4xl font-black text-slate-900">{formatCurrency(supplement)}</span>
            </div>
            <div className="bg-sheet-cyan/10 p-8 rounded-[2rem] border border-cyan-200 shadow-sm text-center">
              <span className="text-xs font-black uppercase text-cyan-900/40 block mb-2 tracking-widest">Vid. etato dalis/d.</span>
              <span className="text-4xl font-black text-slate-900">{formatNumber(dailyFte, 2)}</span>
            </div>
          </div>

          <div className="bg-white rounded-[2rem] shadow-xl shadow-slate-200/50 border border-slate-100 overflow-hidden">
            <div className="p-6 border-b border-slate-50 flex justify-between items-center bg-slate-50/30">
              <h3 className="font-bold text-slate-800 flex items-center gap-2"><Table size={20} className="text-indigo-600" /> Istorija</h3>
              <div className="flex gap-2">
                <button onClick={handleExportCsv} className="flex items-center gap-2 text-xs font-bold text-indigo-600 bg-white px-4 py-2 rounded-xl border border-indigo-100 hover:bg-indigo-50 transition-all"><Download size={16} /> Eksportuoti</button>
              </div>
            </div>

            <div className="overflow-x-auto">
              <table className="w-full text-left">
                <thead className="bg-slate-50/50 text-[10px] font-bold text-slate-400 uppercase tracking-wider">
                  <tr>
                    <th className="px-6 py-4">Darbuotojas</th>
                    <th className="px-4 py-4 text-center">Koef.</th>
                    <th className="px-4 py-4 text-center">Val/D.</th>
                    <th className="px-4 py-4 text-center">Etatas</th>
                    <th className="px-4 py-4 text-right">Suma</th>
                    <th className="px-6 py-4"></th>
                  </tr>
                </thead>
                <tbody className="divide-y divide-slate-50">
                  {filteredEntries.map(e => (
                    <tr key={e.id} className="hover:bg-slate-50/80 transition-colors group">
                      <td className="px-6 py-4">
                        <div className="text-sm font-bold text-slate-800 leading-none mb-1">{e.fullName}</div>
                        <div className="text-[10px] font-bold text-slate-400 uppercase">{e.position}</div>
                      </td>
                      <td className="px-4 py-4 text-center">
                        <span className="text-xs font-mono font-bold text-slate-600 bg-slate-100 px-2 py-1 rounded-md">
                          {formatNumber(e.finalCoefficient, 4)}
                        </span>
                      </td>
                      <td className="px-4 py-4 text-center">
                        <div className="text-xs font-bold text-slate-700">{e.actualHours} val.</div>
                        <div className="text-[9px] text-slate-400">{e.workedDays} d.</div>
                      </td>
                      <td className="px-4 py-4 text-center">
                        <span className="text-xs font-black text-cyan-600">
                          {formatNumber(e.dailyFte, 2)}
                        </span>
                      </td>
                      <td className="px-4 py-4 text-right">
                        <span className="bg-indigo-50 text-indigo-700 px-3 py-1 rounded-full font-extrabold text-xs">
                          {formatCurrency(e.salarySupplement)}
                        </span>
                      </td>
                      <td className="px-6 py-4 text-right">
                        <button onClick={() => setDeleteId(e.id)} className="p-2 text-slate-200 hover:text-red-500 hover:bg-red-50 rounded-lg transition-all">
                          <Trash2 size={16}/>
                        </button>
                      </td>
                    </tr>
                  ))}
                  {filteredEntries.length === 0 && (
                    <tr>
                      <td colSpan={6} className="px-6 py-16 text-center text-slate-400 italic text-sm">Sąrašas tuščias. Įveskite pirmąjį įrašą.</td>
                    </tr>
                  )}
                </tbody>
                {filteredEntries.length > 0 && (
                  <tfoot className="bg-slate-50/30 border-t border-slate-100">
                    <tr>
                      <td colSpan={4} className="px-6 py-4 text-right text-[10px] font-bold text-slate-400 uppercase">Bendra suma:</td>
                      <td className="px-4 py-4 text-right">
                        <span className="text-sm font-black text-indigo-600">{formatCurrency(totalSupplement)}</span>
                      </td>
                      <td></td>
                    </tr>
                  </tfoot>
                )}
              </table>
            </div>
          </div>
        </section>
      </main>

      <SettingsModal isOpen={isSettingsOpen} onClose={() => setIsSettingsOpen(false)} config={config} onSave={setConfig} onClearData={() => {
        setEntries([]);
        localStorage.removeItem(STORAGE_KEY_ENTRIES);
      }} />
      <DeleteConfirmationModal isOpen={!!deleteId} onClose={() => setDeleteId(null)} onConfirm={confirmDelete} />
    </div>
  );
};

export default App;

import React, { useState, useMemo, useEffect, useRef } from 'react';
import { 
  Save, Trash2, Settings, FileText, Calculator, Volume2, 
  StopCircle, Loader2, User, Briefcase, Clock, Percent, 
  Table, Search, Filter, XCircle, Download, Eraser, Info,
  ChevronRight, CalendarDays, History
} from 'lucide-react';
import { GoogleGenAI, Modality } from "@google/genai";
import { WorkloadType, Config, CalculationEntry } from './types.ts';
import { 
  calculateFinalCoefficient, 
  calculateSupplement, 
  calculateDailyFte, 
  formatCurrency, 
  formatNumber 
} from './utils/calculations.ts';
import SettingsModal from './components/SettingsModal.tsx';
import DeleteConfirmationModal from './components/DeleteConfirmationModal.tsx';
import Tooltip from './components/Tooltip.tsx';

const STORAGE_KEY_ENTRIES = 'priemokos_entries_v2';
const STORAGE_KEY_CONFIG = 'priemokos_config_v2';

const App: React.FC = () => {
  const [config, setConfig] = useState<Config>(() => {
    try {
      const saved = localStorage.getItem(STORAGE_KEY_CONFIG);
      return saved ? JSON.parse(saved) : {
        bma: 1798.00,
        avgHours36: 150.6,
        avgHours40: 167.3
      };
    } catch {
      return { bma: 1798.00, avgHours36: 150.6, avgHours40: 167.3 };
    }
  });

  const [entries, setEntries] = useState<CalculationEntry[]>(() => {
    try {
      const saved = localStorage.getItem(STORAGE_KEY_ENTRIES);
      return saved ? JSON.parse(saved) : [];
    } catch {
      return [];
    }
  });

  const [isSettingsOpen, setIsSettingsOpen] = useState(false);
  const [deleteId, setDeleteId] = useState<string | null>(null);
  const [isPlayingAudio, setIsPlayingAudio] = useState(false);
  const [isGeneratingAudio, setIsGeneratingAudio] = useState(false);
  const audioContextRef = useRef<AudioContext | null>(null);
  const sourceNodeRef = useRef<AudioBufferSourceNode | null>(null);

  const [filterName, setFilterName] = useState('');
  const [filterPosition, setFilterPosition] = useState('');

  const [position, setPosition] = useState('');
  const [fullName, setFullName] = useState('');
  const [workloadType, setWorkloadType] = useState<WorkloadType>(WorkloadType.H36);
  const [baseCoef, setBaseCoef] = useState<string>('1.0000');
  const [increasePercent, setIncreasePercent] = useState<string>('0');
  const [actualHours, setActualHours] = useState<string>('');
  const [workedDays, setWorkedDays] = useState<string>('1'); // Pakeista į 1 pagal nutylėjimą
  const [errors, setErrors] = useState<Record<string, string>>({});

  // Duomenų atsiminimo logika iš istorijos
  const historyData = useMemo(() => {
    const positions = new Set<string>();
    const names = new Set<string>();
    const coefficients = new Set<string>();

    entries.forEach(e => {
      if (e.position) positions.add(e.position.trim());
      if (e.fullName) names.add(e.fullName.trim());
      if (e.baseCoefficient) coefficients.add(e.baseCoefficient.toString());
    });

    return {
      positions: Array.from(positions).sort(),
      names: Array.from(names).sort(),
      coefficients: Array.from(coefficients).sort((a, b) => parseFloat(b) - parseFloat(a))
    };
  }, [entries]);

  // Surandame paskutinį naudotą koeficientą konkrečiam žmogui
  const suggestedCoefficient = useMemo(() => {
    if (!fullName.trim()) return null;
    const lastEntry = entries.find(e => e.fullName.toLowerCase() === fullName.trim().toLowerCase());
    return lastEntry ? lastEntry.baseCoefficient : null;
  }, [fullName, entries]);

  useEffect(() => {
    localStorage.setItem(STORAGE_KEY_ENTRIES, JSON.stringify(entries));
    localStorage.setItem(STORAGE_KEY_CONFIG, JSON.stringify(config));
  }, [entries, config]);

  const parsedBaseCoef = parseFloat(baseCoef) || 0;
  const parsedIncrease = parseFloat(increasePercent) || 0;
  const parsedActualHours = parseFloat(actualHours) || 0;
  const parsedWorkedDays = parseFloat(workedDays) || 1;

  const avgMonthlyHours = workloadType === WorkloadType.H36 ? config.avgHours36 : config.avgHours40;
  const finalCoefficient = useMemo(() => calculateFinalCoefficient(parsedBaseCoef, parsedIncrease), [parsedBaseCoef, parsedIncrease]);
  const supplement = useMemo(() => calculateSupplement(finalCoefficient, config.bma, avgMonthlyHours, parsedActualHours), [finalCoefficient, config.bma, avgMonthlyHours, parsedActualHours]);
  const dailyFte = useMemo(() => calculateDailyFte(parsedActualHours, workloadType, parsedWorkedDays), [parsedActualHours, workloadType, parsedWorkedDays]);

  const filteredEntries = useMemo(() => {
    return entries.filter(entry => {
      const matchesName = entry.fullName.toLowerCase().includes(filterName.toLowerCase());
      const matchesPosition = entry.position.toLowerCase().includes(filterPosition.toLowerCase());
      return matchesName && matchesPosition;
    });
  }, [entries, filterName, filterPosition]);

  const totalSupplement = useMemo(() => 
    filteredEntries.reduce((sum, e) => sum + e.salarySupplement, 0), 
    [filteredEntries]
  );

  const handleInputChange = (setter: (v: string) => void, field: string, value: string) => {
    setter(value);
    if (errors[field]) {
      const newErrors = { ...errors };
      delete newErrors[field];
      setErrors(newErrors);
    }
  };

  const resetForm = () => {
    setPosition('');
    setFullName('');
    setActualHours('');
    setWorkedDays('1');
    setErrors({});
  };

  const handleSave = () => {
    const newErrors: Record<string, string> = {};

    if (!position.trim()) newErrors.position = "Prašome įvesti pareigas";
    if (!fullName.trim()) newErrors.fullName = "Prašome įvesti vardą ir pavardę";

    const h = parseFloat(actualHours);
    if (!actualHours.trim()) newErrors.actualHours = "Įveskite valandas";
    else if (isNaN(h) || h <= 0) newErrors.actualHours = "Neteisingas valandų skaičius";

    const d = parseFloat(workedDays);
    if (!workedDays.trim()) newErrors.workedDays = "Įveskite dienas";
    else if (isNaN(d) || d <= 0) newErrors.workedDays = "Neteisingas dienų skaičius";

    if (Object.keys(newErrors).length > 0) {
      setErrors(newErrors);
      return;
    }

    const newEntry: CalculationEntry = {
      id: Date.now().toString(),
      position: position.trim(),
      fullName: fullName.trim(),
      workloadType,
      baseCoefficient: parsedBaseCoef,
      increasePercent: parsedIncrease,
      finalCoefficient,
      actualHours: parsedActualHours,
      workedDays: parsedWorkedDays,
      salarySupplement: supplement,
      dailyFte,
      dateCreated: new Date().toISOString()
    };

    setEntries([newEntry, ...entries]);
    resetForm();
  };

  const confirmDelete = () => {
    if (deleteId) {
      setEntries(entries.filter(i => i.id !== deleteId));
      setDeleteId(null);
    }
  };

  const handleExportCsv = () => {
    if (filteredEntries.length === 0) return;
    const headers = ['Vardas Pavardė', 'Pareigos', 'Režimas', 'Koef.', 'Valandos', 'Dienos', 'Suma', 'Etatas/d.'];
    const rows = filteredEntries.map(e => [
      `"${e.fullName}"`, `"${e.position}"`, e.workloadType === WorkloadType.H36 ? '36h' : '40h',
      formatNumber(e.finalCoefficient, 4).replace(',', '.'), formatNumber(e.actualHours, 1).replace(',', '.'),
      e.workedDays || '', formatNumber(e.salarySupplement, 2).replace(',', '.'), formatNumber(e.dailyFte, 2).replace(',', '.')
    ]);
    const csvContent = headers.join(',') + '\n' + rows.map(r => r.join(',')).join('\n');
    const blob = new Blob(['\ufeff' + csvContent], { type: 'text/csv;charset=utf-8;' });
    const url = URL.createObjectURL(blob);
    const link = document.createElement('a');
    link.href = url;
    link.download = `priemokos_${new Date().toISOString().split('T')[0]}.csv`;
    link.click();
  };

  // Garso gido funkcijos
  const decodeBase64 = (base64: string) => {
    const binaryString = atob(base64);
    const bytes = new Uint8Array(binaryString.length);
    for (let i = 0; i < binaryString.length; i++) bytes[i] = binaryString.charCodeAt(i);
    return bytes;
  };
  const decodeAudioData = async (data: Uint8Array, ctx: AudioContext, sampleRate: number, numChannels: number): Promise<AudioBuffer> => {
    const dataInt16 = new Int16Array(data.buffer);
    const frameCount = dataInt16.length / numChannels;
    const buffer = ctx.createBuffer(numChannels, frameCount, sampleRate);
    for (let ch = 0; ch < numChannels; ch++) {
      const chData = buffer.getChannelData(ch);
      for (let i = 0; i < frameCount; i++) chData[i] = dataInt16[i * numChannels + ch] / 32768.0;
    }
    return buffer;
  };
  const handleAudioGuide = async () => {
    if (isPlayingAudio) { sourceNodeRef.current?.stop(); setIsPlayingAudio(false); return; }
    setIsGeneratingAudio(true);
    try {
      const ai = new GoogleGenAI({ apiKey: process.env.API_KEY });
      const response = await ai.models.generateContent({
        model: 'gemini-2.5-flash-preview-tts',
        contents: [{ parts: [{ text: "Sveiki. Įveskite darbuotojo vardą ir pareigas, o sistema pasiūlys anksčiau naudotus duomenis. Skaičiavimas atliekamas automatiškai." }] }],
        config: { responseModalities: [Modality.AUDIO], speechConfig: { voiceConfig: { prebuiltVoiceConfig: { voiceName: 'Kore' } } } },
      });
      const b64 = response.candidates?.[0]?.content?.parts?.[0]?.inlineData?.data;
      if (!b64) return;
      if (!audioContextRef.current) audioContextRef.current = new (window.AudioContext || (window as any).webkitAudioContext)({ sampleRate: 24000 });
      const buffer = await decodeAudioData(decodeBase64(b64), audioContextRef.current, 24000, 1);
      const source = audioContextRef.current.createBufferSource();
      source.buffer = buffer;
      source.connect(audioContextRef.current.destination);
      source.onended = () => setIsPlayingAudio(false);
      sourceNodeRef.current = source;
      source.start();
      setIsPlayingAudio(true);
    } catch (e) { console.error(e); } finally { setIsGeneratingAudio(false); }
  };

  return (
    <div className="min-h-screen bg-slate-50 p-4 md:p-8">
      <header className="max-w-7xl mx-auto flex flex-col md:flex-row justify-between items-center mb-8 bg-white p-6 rounded-3xl shadow-sm border border-slate-100 gap-4">
        <div className="flex items-center gap-4">
          <div className="bg-indigo-600 p-3 rounded-2xl text-white shadow-indigo-100 shadow-xl">
            <Calculator size={28} />
          </div>
          <div>
            <h1 className="text-2xl font-extrabold text-slate-900 tracking-tight">Priemokų skaičiuoklė 2026</h1>
            <p className="text-xs font-bold text-slate-400 uppercase tracking-widest">BD: {formatCurrency(config.bma)}</p>
          </div>
        </div>
        <div className="flex gap-3">
          <button onClick={handleAudioGuide} className={`flex items-center gap-2 px-4 py-2 rounded-2xl transition-all font-bold text-sm ${isPlayingAudio ? 'bg-red-50 text-red-600' : 'bg-slate-100 text-slate-600'}`}>
            {isGeneratingAudio ? <Loader2 size={20} className="animate-spin" /> : isPlayingAudio ? <StopCircle size={20} /> : <Volume2 size={20} />}
            <span className="hidden sm:inline">{isPlayingAudio ? 'Sustabdyti' : 'Gidas'}</span>
          </button>
          <button onClick={() => setIsSettingsOpen(true)} className="p-3 bg-slate-100 text-slate-600 rounded-2xl hover:bg-slate-200 transition-colors"><Settings size={20} /></button>
        </div>
      </header>

      <main className="max-w-7xl mx-auto grid grid-cols-1 lg:grid-cols-12 gap-8">
        <section className="lg:col-span-5 space-y-6">
          <div className="bg-white p-8 rounded-[2rem] shadow-xl shadow-slate-200/50 border border-slate-100">
            <h2 className="text-lg font-bold text-slate-800 mb-6 flex items-center gap-2">
              <FileText size={20} className="text-indigo-600" /> Įvesti duomenis
            </h2>

            <div className="space-y-5">
              {/* Vardas Pavardė su atmintimi */}
              <div className="space-y-1.5">
                <label className="text-xs font-bold text-slate-500 uppercase ml-1 flex justify-between">
                  <span>1. Darbuotojas</span>
                  {suggestedCoefficient && <span className="text-[10px] text-indigo-500 lowercase flex items-center gap-1"><History size={10}/> istorija rasta</span>}
                </label>
                <div className="relative">
                  <User className="absolute left-4 top-1/2 -translate-y-1/2 text-slate-400" size={18} />
                  <input 
                    type="text" 
                    list="names-list"
                    value={fullName} 
                    onChange={e => handleInputChange(setFullName, 'fullName', e.target.value)} 
                    placeholder="Vardas Pavardė" 
                    className={`w-full pl-12 pr-4 py-3 bg-slate-50 border rounded-2xl outline-none transition-all focus:ring-4 ${errors.fullName ? 'border-red-300 focus:ring-red-50' : 'border-slate-100 focus:ring-indigo-50'}`} 
                  />
                  <datalist id="names-list">
                    {historyData.names.map(n => <option key={n} value={n} />)}
                  </datalist>
                </div>
                {errors.fullName && <p className="text-[10px] text-red-500 font-bold uppercase ml-1">{errors.fullName}</p>}
              </div>

              {/* Pareigos su atmintimi */}
              <div className="space-y-1.5">
                <label className="text-xs font-bold text-slate-500 uppercase ml-1">2. Pareigos</label>
                <div className="relative">
                  <Briefcase className="absolute left-4 top-1/2 -translate-y-1/2 text-slate-400" size={18} />
                  <input 
                    type="text" 
                    list="positions-list"
                    value={position} 
                    onChange={e => handleInputChange(setPosition, 'position', e.target.value)} 
                    placeholder="Pvz.: Mokytojas" 
                    className={`w-full pl-12 pr-4 py-3 bg-slate-50 border rounded-2xl outline-none transition-all focus:ring-4 ${errors.position ? 'border-red-300 focus:ring-red-50' : 'border-slate-100 focus:ring-indigo-50'}`} 
                  />
                  <datalist id="positions-list">
                    {historyData.positions.map(p => <option key={p} value={p} />)}
                  </datalist>
