import React, { useMemo } from 'react';
import { 
  BarChart, Bar, XAxis, YAxis, CartesianGrid, Tooltip, Legend, ResponsiveContainer,
  PieChart, Pie, Cell, LineChart, Line
} from 'recharts';
import { CalculationEntry } from '../types';
import { formatCurrency, formatNumber } from '../utils/calculations';
import { TrendingUp, Users, Briefcase, Calendar } from 'lucide-react';

interface StatisticsViewProps {
  entries: CalculationEntry[];
}

const COLORS = ['#4f46e5', '#06b6d4', '#f59e0b', '#10b981', '#ec4899', '#8b5cf6'];

const StatisticsView: React.FC<StatisticsViewProps> = ({ entries }) => {
  // 1. Agregacija pagal mėnesius
  const monthlyData = useMemo(() => {
    const months: Record<string, number> = {};
    entries.forEach(e => {
      const date = new Date(e.dateCreated);
      const key = `${date.getFullYear()}-${(date.getMonth() + 1).toString().padStart(2, '0')}`;
      months[key] = (months[key] || 0) + e.salarySupplement;
    });

    return Object.entries(months)
      .sort(([a], [b]) => a.localeCompare(b))
      .map(([month, total]) => ({
        name: month,
        suma: parseFloat(total.toFixed(2))
      }));
  }, [entries]);

  // 2. Agregacija pagal pareigas
  const positionData = useMemo(() => {
    const positions: Record<string, { total: number; count: number }> = {};
    entries.forEach(e => {
      if (!positions[e.position]) positions[e.position] = { total: 0, count: 0 };
      positions[e.position].total += e.salarySupplement;
      positions[e.position].count += 1;
    });

    return Object.entries(positions).map(([name, data]) => ({
      name,
      value: parseFloat(data.total.toFixed(2)),
      count: data.count
    }));
  }, [entries]);

  // 3. Bendri rodikliai
  const stats = useMemo(() => {
    const total = entries.reduce((sum, e) => sum + e.salarySupplement, 0);
    const uniqueEmployees = new Set(entries.map(e => e.fullName)).size;
    const avgPerEmployee = uniqueEmployees > 0 ? total / uniqueEmployees : 0;

    return {
      total,
      uniqueEmployees,
      avgPerEmployee,
      entryCount: entries.length
    };
  }, [entries]);

  if (entries.length === 0) {
    return (
      <div className="flex flex-col items-center justify-center py-20 text-slate-400 bg-white rounded-[2rem] border border-dashed border-slate-200">
        <TrendingUp size={48} className="mb-4 opacity-20" />
        <p className="text-lg font-medium">Nėra duomenų statistikai generuoti</p>
        <p className="text-sm">Išsaugokite bent vieną priemokos skaičiavimą.</p>
      </div>
    );
  }

  return (
    <div className="space-y-8 animate-in fade-in slide-in-from-bottom-4 duration-500">
      {/* Kortelės */}
      <div className="grid grid-cols-1 md:grid-cols-2 lg:grid-cols-4 gap-6">
        <div className="bg-white p-6 rounded-3xl border border-slate-100 shadow-sm">
          <div className="bg-indigo-50 w-10 h-10 rounded-xl flex items-center justify-center text-indigo-600 mb-4">
            <TrendingUp size={20} />
          </div>
          <p className="text-xs font-bold text-slate-400 uppercase tracking-wider">Iš viso priemokų</p>
          <p className="text-2xl font-black text-slate-900">{formatCurrency(stats.total)}</p>
        </div>

        <div className="bg-white p-6 rounded-3xl border border-slate-100 shadow-sm">
          <div className="bg-cyan-50 w-10 h-10 rounded-xl flex items-center justify-center text-cyan-600 mb-4">
            <Users size={20} />
          </div>
          <p className="text-xs font-bold text-slate-400 uppercase tracking-wider">Darbuotojų skaičius</p>
          <p className="text-2xl font-black text-slate-900">{stats.uniqueEmployees}</p>
        </div>

        <div className="bg-white p-6 rounded-3xl border border-slate-100 shadow-sm">
          <div className="bg-orange-50 w-10 h-10 rounded-xl flex items-center justify-center text-orange-600 mb-4">
            <Calendar size={20} />
          </div>
          <p className="text-xs font-bold text-slate-400 uppercase tracking-wider">Vidurkis / darbuotojui</p>
          <p className="text-2xl font-black text-slate-900">{formatCurrency(stats.avgPerEmployee)}</p>
        </div>

        <div className="bg-white p-6 rounded-3xl border border-slate-100 shadow-sm">
          <div className="bg-emerald-50 w-10 h-10 rounded-xl flex items-center justify-center text-emerald-600 mb-4">
            <Briefcase size={20} />
          </div>
          <p className="text-xs font-bold text-slate-400 uppercase tracking-wider">Iš viso įrašų</p>
          <p className="text-2xl font-black text-slate-900">{stats.entryCount}</p>
        </div>
      </div>

      <div className="grid grid-cols-1 lg:grid-cols-2 gap-8">
        {/* Mėnesio dinamika */}
        <div className="bg-white p-8 rounded-[2rem] border border-slate-100 shadow-sm">
          <h3 className="text-sm font-bold text-slate-800 mb-6 flex items-center gap-2">
            <Calendar size={16} className="text-indigo-600" /> Mėnesinė priemokų suma (EUR)
          </h3>
          <div className="h-[300px] w-full">
            <ResponsiveContainer width="100%" height="100%">
              <BarChart data={monthlyData}>
                <CartesianGrid strokeDasharray="3 3" vertical={false} stroke="#f1f5f9" />
                <XAxis dataKey="name" axisLine={false} tickLine={false} tick={{ fontSize: 10, fill: '#94a3b8' }} />
                <YAxis axisLine={false} tickLine={false} tick={{ fontSize: 10, fill: '#94a3b8' }} tickFormatter={(val) => `${val}€`} />
                <Tooltip 
                  cursor={{ fill: '#f8fafc' }}
                  contentStyle={{ borderRadius: '12px', border: 'none', boxShadow: '0 10px 15px -3px rgb(0 0 0 / 0.1)' }}
                  formatter={(value: number) => [formatCurrency(value), 'Suma']}
                />
                <Bar dataKey="suma" fill="#4f46e5" radius={[4, 4, 0, 0]} />
              </BarChart>
            </ResponsiveContainer>
