server {
    listen 8080;
    server_name localhost;

    location / {
        root /usr/share/nginx/html;
        index index.html index.htm;
        try_files $uri $uri/ /index.html;

        # Svarbu: leidžiame naršyklei suprasti TSX failus kaip JS modulius, 
        # jei naršyklė palaiko tiesioginį importą (priklauso nuo aplinkos).
