                  <span className="text-4xl font-black text-slate-900">{formatCurrency(supplement)}</span>
                </div>
                <div className="bg-sheet-cyan/10 p-8 rounded-[2rem] border border-cyan-200 shadow-sm text-center">
                  <span className="text-xs font-black uppercase text-cyan-900/40 block mb-2 tracking-widest">Vid. etatas/d.</span>
                  <span className="text-4xl font-black text-slate-900">{formatNumber(dailyFte, 2)}</span>
                </div>
              </div>

              <div className="bg-white rounded-[2rem] shadow-xl shadow-slate-200/50 border border-slate-100 overflow-hidden">
                <div className="p-6 border-b border-slate-50 flex justify-between items-center bg-slate-50/30">
                  <h3 className="font-bold text-slate-800 flex items-center gap-2"><Table size={20} className="text-indigo-600" /> Istorija</h3>
                  <button onClick={handleExportCsv} className="flex items-center gap-2 text-xs font-bold text-indigo-600 bg-white px-4 py-2 rounded-xl border border-indigo-100 hover:bg-indigo-50 transition-all"><Download size={16} /> CSV</button>
                </div>
                <div className="overflow-x-auto">
                  <table className="w-full text-left">
                    <thead className="bg-slate-50/50 text-[10px] font-bold text-slate-400 uppercase tracking-wider">
                      <tr><th className="px-6 py-4">Darbuotojas</th><th className="px-4 py-4 text-center">Koef.</th><th className="px-4 py-4 text-center">Val/D.</th><th className="px-4 py-4 text-center">Etatas</th><th className="px-4 py-4 text-right">Suma</th><th className="px-6 py-4"></th></tr>
                    </thead>
                    <tbody className="divide-y divide-slate-50">
                      {filteredEntries.map(e => (
                        <tr key={e.id} className="hover:bg-slate-50/80 transition-colors group">
                          <td className="px-6 py-4"><div className="text-sm font-bold text-slate-800 mb-0.5">{e.fullName}</div><div className="text-[10px] font-bold text-slate-400 uppercase">{e.position}</div></td>
                          <td className="px-4 py-4 text-center text-xs font-mono font-bold text-slate-600">{formatNumber(e.finalCoefficient, 4)}</td>
                          <td className="px-4 py-4 text-center"><div className="text-xs font-bold text-slate-700">{e.actualHours} val.</div><div className="text-[9px] text-slate-400">{e.workedDays} d.</div></td>
                          <td className="px-4 py-4 text-center"><span className="text-xs font-black text-cyan-600">{formatNumber(e.dailyFte, 2)}</span></td>
                          <td className="px-4 py-4 text-right"><span className="bg-indigo-50 text-indigo-700 px-3 py-1 rounded-full font-extrabold text-xs">{formatCurrency(e.salarySupplement)}</span></td>
                          <td className="px-6 py-4 text-right"><button onClick={() => setDeleteId(e.id)} className="p-2 text-slate-200 hover:text-red-500 rounded-lg transition-all"><Trash2 size={16}/></button></td>
                        </tr>
                      ))}
                      {filteredEntries.length === 0 && <tr><td colSpan={6} className="px-6 py-16 text-center text-slate-400 italic text-sm">Nėra įrašų</td></tr>}
                    </tbody>
                  </table>
                </div>
              </div>
            </section>
          </div>
        ) : (
          <StatisticsView entries={entries} />
        )}
      </main>

      <SettingsModal isOpen={isSettingsOpen} onClose={() => setIsSettingsOpen(false)} config={config} onSave={setConfig} onClearData={() => {
        setEntries([]);
        localStorage.removeItem(STORAGE_KEY_ENTRIES);
      }} />
      <DeleteConfirmationModal isOpen={!!deleteId} onClose={() => setDeleteId(null)} onConfirm={confirmDelete} />
    </div>
  );
};

