import React, { useState, useEffect } from 'react';
import { X, Lock, Unlock, AlertCircle, Calculator, ArrowRight, ExternalLink, Trash2 } from 'lucide-react';
import { Config } from '../types';
import { isConfigEditable, formatNumber } from '../utils/calculations';

interface SettingsModalProps {
  isOpen: boolean;
  onClose: () => void;
  config: Config;
  onSave: (newConfig: Config) => void;
  onClearData: () => void;
}

const SettingsModal: React.FC<SettingsModalProps> = ({ isOpen, onClose, config, onSave, onClearData }) => {
  const [localConfig, setLocalConfig] = useState<Config>(config);
  const [error, setError] = useState<string>('');
  const canEditHours = isConfigEditable();

  useEffect(() => {
    setLocalConfig(config);
    setError('');
  }, [config, isOpen]);

  const handleBmaChange = (e: React.ChangeEvent<HTMLInputElement>) => {
    const value = parseFloat(e.target.value);
    const newBma = isNaN(value) ? 0 : value;
    setLocalConfig({ ...localConfig, bma: newBma });
    if (isNaN(value) || value <= 0) setError('BD turi būti teigiamas skaičius');
    else setError('');
  };

  const handleHourChange = (field: keyof Config, value: string) => {
    const numValue = parseFloat(value);
    setLocalConfig({ ...localConfig, [field]: isNaN(numValue) ? 0 : numValue });
  };

  const handleSave = () => {
    if (localConfig.bma <= 0) return;
    onSave(localConfig);
    onClose();
  };

  if (!isOpen) return null;

  return (
    <div className="fixed inset-0 z-50 flex items-center justify-center bg-black/50 backdrop-blur-sm p-4">
      <div className="bg-white rounded-3xl shadow-2xl w-full max-w-md overflow-hidden max-h-[90vh] overflow-y-auto animate-in zoom-in-95 duration-200">
