import React, { useState, useEffect } from 'react';
import { X, Lock, Unlock, AlertCircle, Calculator, ArrowRight, ExternalLink, Trash2, BookOpen } from 'lucide-react';
import { Config } from '../types';
import { isConfigEditable, formatNumber } from '../utils/calculations';

interface SettingsModalProps {
  isOpen: boolean;
  onClose: () => void;
  config: Config;
  onSave: (newConfig: Config) => void;
  onClearData: () => void;
}

const SettingsModal: React.FC<SettingsModalProps> = ({ isOpen, onClose, config, onSave, onClearData }) => {
  const [localConfig, setLocalConfig] = useState<Config>(config);
  const [error, setError] = useState<string>('');
  const canEditHours = isConfigEditable();

  useEffect(() => {
    setLocalConfig(config);
    setError('');
  }, [config, isOpen]);

  const handleBmaChange = (e: React.ChangeEvent<HTMLInputElement>) => {
    const value = parseFloat(e.target.value);
    const newBma = isNaN(value) ? 0 : value;
    setLocalConfig({ ...localConfig, bma: newBma });
    if (isNaN(value) || value <= 0) setError('BD turi būti teigiamas skaičius');
    else setError('');
  };

  const handleHourChange = (field: keyof Config, value: string) => {
    const numValue = parseFloat(value);
    setLocalConfig({ ...localConfig, [field]: isNaN(numValue) ? 0 : numValue });
  };

  const handleSave = () => {
    if (localConfig.bma <= 0) return;
    onSave(localConfig);
    onClose();
  };

  if (!isOpen) return null;

  const legalLinks = [
    {
      title: 'Bazinio dydžio nustatymo įstatymas',
      url: 'https://www.e-tar.lt/portal/lt/legalAct/8253c29006c711ee9978886e85107ab2/asr',
    },
    {
      title: 'Pagrindiniai socialiniai rodikliai (Sodra)',
      url: 'https://sodra.lt/statistika/pagrindiniai-socialiniai-rodikliai',
    },
    {
      title: 'Vidutinio darbo laiko skaičiai (TAGIDAS)',
      url: 'https://www.tagidas.lt/savadai/9002/',
    }
  ];

  return (
    <div className="fixed inset-0 z-50 flex items-center justify-center bg-black/50 backdrop-blur-sm p-4">
      <div className="bg-white rounded-3xl shadow-2xl w-full max-w-md overflow-hidden max-h-[90vh] overflow-y-auto animate-in zoom-in-95 duration-200">
        <div className="bg-slate-100 px-6 py-4 flex justify-between items-center border-b border-slate-200 sticky top-0 z-10">
          <h3 className="text-lg font-bold text-slate-800">Sistemos nustatymai</h3>
          <button onClick={onClose} className="text-slate-500 hover:text-slate-700 transition-colors"><X size={24} /></button>
        </div>

        <div className="p-6 space-y-6">
          {/* Bazinis Dydis */}
          <div>
            <label className="block text-sm font-bold text-slate-700 mb-1">Bazinis dydis (BD)</label>
            <div className="relative">
              <input 
                type="number" 
                step="0.01" 
                value={localConfig.bma} 
                onChange={handleBmaChange} 
                className="w-full px-4 py-3 bg-slate-50 border border-slate-200 rounded-xl focus:ring-4 focus:ring-indigo-50 outline-none font-bold text-indigo-700" 
              />
              <div className="absolute right-4 top-1/2 -translate-y-1/2 text-slate-400 text-sm font-bold">€</div>
            </div>
            <p className="text-[10px] text-slate-400 mt-1 uppercase font-bold tracking-wider">2026 m. patvirtintas: 1798,00 €</p>
          </div>

          <div className="h-px bg-slate-100" />

          {/* Vidutiniai Valandų Skaičiai */}
          <div className="space-y-4">
            <div className="flex items-center justify-between">
              <h4 className="font-bold text-slate-800 text-sm flex items-center gap-2">
                <Calculator size={16} className="text-indigo-600" /> 2026 m. vidutiniai val. skaičiai
              </h4>
              {!canEditHours && (
                <div className="group relative">
                  <span className="flex items-center text-[9px] text-amber-600 bg-amber-50 px-2 py-1 rounded-full font-bold uppercase cursor-help">
                    <Lock size={10} className="mr-1" /> Fiksuota
                  </span>
                  <div className="absolute bottom-full right-0 mb-2 w-48 p-2 bg-slate-800 text-white text-[10px] rounded-lg opacity-0 group-hover:opacity-100 transition-opacity pointer-events-none z-20">
                    Šie rodikliai nustatomi teisės aktais metams. Redaguoti galima tik sausio mėnesį.
                  </div>
                </div>
              )}
            </div>

            <div className="grid grid-cols-2 gap-4">
              <div className="space-y-1">
                <label className="text-[10px] font-black text-slate-400 uppercase tracking-widest ml-1">36 val. norma</label>
                <input 
                  type="number" 
                  step="0.01"
                  disabled={!canEditHours}
                  value={localConfig.avgHours36}
                  onChange={(e) => handleHourChange('avgHours36', e.target.value)}
                  className={`w-full p-3 border rounded-xl font-mono text-sm font-bold ${!canEditHours ? 'bg-slate-50 text-slate-500 border-slate-100' : 'bg-white border-slate-200 text-indigo-600'}`}
                />
                <p className="text-[9px] text-slate-400 italic ml-1">Mokytojams (150.48)</p>
              </div>
              <div className="space-y-1">
                <label className="text-[10px] font-black text-slate-400 uppercase tracking-widest ml-1">40 val. norma</label>
                <input 
                  type="number" 
                  step="0.01"
                  disabled={!canEditHours}
                  value={localConfig.avgHours40}
                  onChange={(e) => handleHourChange('avgHours40', e.target.value)}
                  className={`w-full p-3 border rounded-xl font-mono text-sm font-bold ${!canEditHours ? 'bg-slate-50 text-slate-500 border-slate-100' : 'bg-white border-slate-200 text-indigo-600'}`}
                />
                <p className="text-[9px] text-slate-400 italic ml-1">Kitiems (166.83)</p>
              </div>
            </div>
          </div>

          <div className="h-px bg-slate-100" />

          {/* Teisinė Informacija */}
          <div className="space-y-3">
            <h4 className="font-bold text-slate-800 text-sm flex items-center gap-2">
              <BookOpen size={16} className="text-indigo-600" /> Teisinė informacija ir šaltiniai
            </h4>
            <ul className="space-y-2">
              {legalLinks.map((link, idx) => (
                <li key={idx}>
                  <a 
                    href={link.url} 
                    target="_blank" 
                    rel="noopener noreferrer"
                    className="flex items-center justify-between gap-2 p-2 bg-slate-50 rounded-xl border border-slate-100 hover:border-indigo-200 hover:bg-white transition-all group"
                  >
                    <span className="text-[10px] font-bold text-slate-600 group-hover:text-indigo-600">{link.title}</span>
                    <ExternalLink size={12} className="text-slate-400 group-hover:text-indigo-600 shrink-0" />
                  </a>
                </li>
              ))}
            </ul>
          </div>

          <div className="h-px bg-slate-100" />

          {/* Duomenų Valdymas */}
          <div className="bg-red-50 p-4 rounded-2xl border border-red-100">
            <h4 className="text-xs font-black text-red-800 uppercase tracking-wider mb-2 flex items-center gap-2">
              <AlertCircle size={14} /> Duomenų valdymas
            </h4>
            <button 
              onClick={() => {
                if (confirm('Ar tikrai norite ištrinti visus skaičiavimo įrašus?')) {
                  onClearData();
                  onClose();
                }
              }}
              className="w-full py-2.5 bg-white text-red-600 border border-red-200 rounded-xl text-xs font-bold hover:bg-red-600 hover:text-white transition-all flex items-center justify-center gap-2"
            >
              <Trash2 size={14} /> Išvalyti visą istoriją
            </button>
          </div>
        </div>

        <div className="bg-slate-50 px-6 py-4 flex gap-3">
          <button 
            onClick={onClose} 
            className="flex-1 py-3 text-slate-600 font-bold text-sm hover:bg-slate-100 rounded-xl transition-colors"
          >
            Atšaukti
          </button>
          <button 
            onClick={handleSave} 
            className="flex-1 py-3 bg-indigo-600 text-white font-bold text-sm rounded-xl shadow-lg shadow-indigo-100 hover:bg-indigo-700 transition-all"
          >
            Išsaugoti
          </button>
        </div>
      </div>
    </div>
  );
};

export default SettingsModal;

import React, { useState, useMemo, useEffect, useRef } from 'react';
import { 
  Save, Trash2, Settings, FileText, Calculator, Volume2, 
  StopCircle, Loader2, User, Briefcase, Clock, Percent, 
  Table, Search, Filter, XCircle, Download, Eraser, Info,
  ChevronRight, CalendarDays, History, TrendingUp, LayoutGrid,
  ExternalLink, BookMarked
} from 'lucide-react';
import { GoogleGenAI, Modality } from "@google/genai";
import { WorkloadType, Config, CalculationEntry } from './types.ts';
import { 
  calculateFinalCoefficient, 
  calculateSupplement, 
  calculateDailyFte, 
  formatCurrency, 
  formatNumber 
} from './utils/calculations.ts';
import SettingsModal from './components/SettingsModal.tsx';
import DeleteConfirmationModal from './components/DeleteConfirmationModal.tsx';
import Tooltip from './components/Tooltip.tsx';
import StatisticsView from './components/StatisticsView.tsx';

const STORAGE_KEY_ENTRIES = 'priemokos_entries_v2';
const STORAGE_KEY_CONFIG = 'priemokos_config_v2';

const App: React.FC = () => {
  const [currentView, setCurrentView] = useState<'calculator' | 'stats'>('calculator');
  const [config, setConfig] = useState<Config>(() => {
    try {
      const saved = localStorage.getItem(STORAGE_KEY_CONFIG);
      return saved ? JSON.parse(saved) : {
        bma: 1798.00,
        avgHours36: 150.48,
        avgHours40: 166.83
      };
    } catch {
      return { bma: 1798.00, avgHours36: 150.48, avgHours40: 166.83 };
    }
  });

  const [entries, setEntries] = useState<CalculationEntry[]>(() => {
    try {
      const saved = localStorage.getItem(STORAGE_KEY_ENTRIES);
      return saved ? JSON.parse(saved) : [];
    } catch {
      return [];
    }
  });

  const [isSettingsOpen, setIsSettingsOpen] = useState(false);
  const [deleteId, setDeleteId] = useState<string | null>(null);
  const [isPlayingAudio, setIsPlayingAudio] = useState(false);
  const [isGeneratingAudio, setIsGeneratingAudio] = useState(false);
  const audioContextRef = useRef<AudioContext | null>(null);
  const sourceNodeRef = useRef<AudioBufferSourceNode | null>(null);

  const [filterName, setFilterName] = useState('');
  const [filterPosition, setFilterPosition] = useState('');

  const [position, setPosition] = useState('');
  const [fullName, setFullName] = useState('');
  const [workloadType, setWorkloadType] = useState<WorkloadType>(WorkloadType.H36);
  const [baseCoef, setBaseCoef] = useState<string>('1.0000');
  const [increasePercent, setIncreasePercent] = useState<string>('0');
  const [actualHours, setActualHours] = useState<string>('');
  const [workedDays, setWorkedDays] = useState<string>('1'); 
  const [errors, setErrors] = useState<Record<string, string>>({});

  const historyData = useMemo(() => {
    const positions = new Set<string>();
    const names = new Set<string>();
    const coefficients = new Set<string>();

    entries.forEach(e => {
      if (e.position) positions.add(e.position.trim());
      if (e.fullName) names.add(e.fullName.trim());
      if (e.baseCoefficient) coefficients.add(e.baseCoefficient.toString());
    });

    return {
      positions: Array.from(positions).sort(),
      names: Array.from(names).sort(),
      coefficients: Array.from(coefficients).sort((a, b) => parseFloat(b) - parseFloat(a))
    };
  }, [entries]);

  const suggestedCoefficient = useMemo(() => {
    if (!fullName.trim()) return null;
    const lastEntry = entries.find(e => e.fullName.toLowerCase() === fullName.trim().toLowerCase());
    return lastEntry ? lastEntry.baseCoefficient : null;
  }, [fullName, entries]);

  useEffect(() => {
    localStorage.setItem(STORAGE_KEY_ENTRIES, JSON.stringify(entries));
    localStorage.setItem(STORAGE_KEY_CONFIG, JSON.stringify(config));
  }, [entries, config]);

  const parsedBaseCoef = parseFloat(baseCoef) || 0;
  const parsedIncrease = parseFloat(increasePercent) || 0;
  const parsedActualHours = parseFloat(actualHours) || 0;
  const parsedWorkedDays = parseFloat(workedDays) || 1;

  const avgMonthlyHours = workloadType === WorkloadType.H36 ? config.avgHours36 : config.avgHours40;
  const finalCoefficient = useMemo(() => calculateFinalCoefficient(parsedBaseCoef, parsedIncrease), [parsedBaseCoef, parsedIncrease]);
  const supplement = useMemo(() => calculateSupplement(finalCoefficient, config.bma, avgMonthlyHours, parsedActualHours), [finalCoefficient, config.bma, avgMonthlyHours, parsedActualHours]);
  const dailyFte = useMemo(() => calculateDailyFte(parsedActualHours, workloadType, parsedWorkedDays), [parsedActualHours, workloadType, parsedWorkedDays]);

  const filteredEntries = useMemo(() => {
    return entries.filter(entry => {
      const matchesName = entry.fullName.toLowerCase().includes(filterName.toLowerCase());
      const matchesPosition = entry.position.toLowerCase().includes(filterPosition.toLowerCase());
      return matchesName && matchesPosition;
    });
  }, [entries, filterName, filterPosition]);

  const handleInputChange = (setter: (v: string) => void, field: string, value: string) => {
    setter(value);
    if (errors[field]) {
      const newErrors = { ...errors };
      delete newErrors[field];
      setErrors(newErrors);
    }
  };

  const resetForm = () => {
    setPosition('');
    setFullName('');
    setActualHours('');
    setWorkedDays('1');
    setErrors({});
  };

  const handleSave = () => {
    const newErrors: Record<string, string> = {};
    if (!position.trim()) newErrors.position = "Prašome įvesti pareigas";
    if (!fullName.trim()) newErrors.fullName = "Prašome įvesti vardą ir pavardę";
    const h = parseFloat(actualHours);
    if (!actualHours.trim()) newErrors.actualHours = "Įveskite valandas";
    else if (isNaN(h) || h <= 0) newErrors.actualHours = "Neteisingas valandų skaičius";
    const d = parseFloat(workedDays);
    if (!workedDays.trim()) newErrors.workedDays = "Įveskite dienas";
    else if (isNaN(d) || d <= 0) newErrors.workedDays = "Neteisingas dienų skaičius";

    if (Object.keys(newErrors).length > 0) {
      setErrors(newErrors);
      return;
    }

    const newEntry: CalculationEntry = {
      id: Date.now().toString(),
      position: position.trim(),
      fullName: fullName.trim(),
      workloadType,
      baseCoefficient: parsedBaseCoef,
      increasePercent: parsedIncrease,
      finalCoefficient,
      actualHours: parsedActualHours,
      workedDays: parsedWorkedDays,
      salarySupplement: supplement,
      dailyFte,
      dateCreated: new Date().toISOString()
    };

    setEntries([newEntry, ...entries]);
    resetForm();
  };

  const confirmDelete = () => {
    if (deleteId) {
      setEntries(entries.filter(i => i.id !== deleteId));
      setDeleteId(null);
    }
  };

  const handleExportCsv = () => {
    if (filteredEntries.length === 0) return;
    const headers = ['Vardas Pavardė', 'Pareigos', 'Režimas', 'Koef.', 'Valandos', 'Dienos', 'Suma', 'Etatas/d.'];
    const rows = filteredEntries.map(e => [
      `"${e.fullName}"`, `"${e.position}"`, e.workloadType === WorkloadType.H36 ? '36h' : '40h',
      formatNumber(e.finalCoefficient, 4).replace(',', '.'), formatNumber(e.actualHours, 1).replace(',', '.'),
      e.workedDays || '', formatNumber(e.salarySupplement, 2).replace(',', '.'), formatNumber(e.dailyFte, 2).replace(',', '.')
    ]);
    const csvContent = headers.join(',') + '\n' + rows.map(r => r.join(',')).join('\n');
    const blob = new Blob(['\ufeff' + csvContent], { type: 'text/csv;charset=utf-8;' });
    const url = URL.createObjectURL(blob);
    const link = document.createElement('a');
    link.href = url;
    link.download = `priemokos_${new Date().toISOString().split('T')[0]}.csv`;
    link.click();
  };

  const decodeBase64 = (base64: string) => {
    const binaryString = window.atob(base64);
    const bytes = new Uint8Array(binaryString.length);
    for (let i = 0; i < binaryString.length; i++) bytes[i] = binaryString.charCodeAt(i);
    return bytes;
  };

  const decodeAudioData = async (data: Uint8Array, ctx: AudioContext, sampleRate: number, numChannels: number): Promise<AudioBuffer> => {
    const dataInt16 = new Int16Array(data.buffer, data.byteOffset, data.byteLength / 2);
    const frameCount = dataInt16.length / numChannels;
    const buffer = ctx.createBuffer(numChannels, frameCount, sampleRate);
    for (let ch = 0; ch < numChannels; ch++) {
      const chData = buffer.getChannelData(ch);
      for (let i = 0; i < frameCount; i++) chData[i] = dataInt16[i * numChannels + ch] / 32768.0;
    }
    return buffer;
  };

  const handleAudioGuide = async () => {
    if (isPlayingAudio) { 
      if (sourceNodeRef.current) {
        try { sourceNodeRef.current.stop(); } catch(e) {}
      }
      setIsPlayingAudio(false); 
      return; 
    }

    setIsGeneratingAudio(true);
    try {
      if (!audioContextRef.current) {
        audioContextRef.current = new (window.AudioContext || (window as any).webkitAudioContext)({ sampleRate: 24000 });
      }
      if (audioContextRef.current.state === 'suspended') {
        await audioContextRef.current.resume();
      }

      const ai = new GoogleGenAI({ apiKey: process.env.API_KEY });
      const prompt = currentView === 'calculator' 
        ? "Esate skaičiuoklės skiltyje. Čia galite suvesti darbuotojo vardą, pareigas, koeficientą bei dirbtas valandas. Paspaudę išsaugoti, matysite apskaičiuotą priemoką istorijos lentelėje."
        : "Esate statistikos skiltyje. Čia galite matyti bendrą priemokų sumą, darbuotojų skaičių bei išmokų pasiskirstymą pagal pareigas.";

      const response = await ai.models.generateContent({
        model: 'gemini-2.5-flash-preview-tts',
        contents: [{ parts: [{ text: prompt }] }],
        config: { 
          responseModalities: [Modality.AUDIO], 
          speechConfig: { 
            voiceConfig: { 
              prebuiltVoiceConfig: { voiceName: 'Kore' } 
            } 
          } 
        },
      });

      const b64 = response.candidates?.[0]?.content?.parts?.[0]?.inlineData?.data;
      if (!b64) throw new Error("Nepavyko gauti garso duomenų");

      const buffer = await decodeAudioData(decodeBase64(b64), audioContextRef.current, 24000, 1);
      const source = audioContextRef.current.createBufferSource();
      source.buffer = buffer;
      source.connect(audioContextRef.current.destination);
      source.onended = () => {
        setIsPlayingAudio(false);
        sourceNodeRef.current = null;
      };
      sourceNodeRef.current = source;
      source.start();
      setIsPlayingAudio(true);
    } catch (e) { 
      console.error("Audio Guide Error:", e);
      alert("Atsiprašome, nepavyko paleisti audio gido. Patikrinkite interneto ryšį.");
    } finally { 
      setIsGeneratingAudio(false); 
    }
  };

  return (
    <div className="min-h-screen bg-slate-50 p-4 md:p-8">
      <header className="max-w-7xl mx-auto flex flex-col md:flex-row justify-between items-center mb-8 bg-white p-6 rounded-3xl shadow-sm border border-slate-100 gap-4">
        <div className="flex items-center gap-4">
          <div className="bg-indigo-600 p-3 rounded-2xl text-white shadow-indigo-100 shadow-xl">
            <Calculator size={28} />
          </div>
          <div>
            <h1 className="text-2xl font-extrabold text-slate-900 tracking-tight">Priemokų skaičiuoklė 2026</h1>
            <div className="flex gap-4 mt-1">
               <p className="text-[10px] font-bold text-slate-400 uppercase tracking-widest">BD: {formatCurrency(config.bma)}</p>
               <div className="flex bg-slate-100 p-1 rounded-lg">
                  <button 
                    onClick={() => setCurrentView('calculator')}
                    className={`px-3 py-1 rounded-md text-[10px] font-bold uppercase tracking-wider transition-all flex items-center gap-1.5 ${currentView === 'calculator' ? 'bg-white text-indigo-600 shadow-sm' : 'text-slate-400 hover:text-slate-600'}`}
                  >
                    <LayoutGrid size={12} /> Skaičiuoklė
                  </button>
                  <button 
                    onClick={() => setCurrentView('stats')}
                    className={`px-3 py-1 rounded-md text-[10px] font-bold uppercase tracking-wider transition-all flex items-center gap-1.5 ${currentView === 'stats' ? 'bg-white text-indigo-600 shadow-sm' : 'text-slate-400 hover:text-slate-600'}`}
                  >
                    <TrendingUp size={12} /> Statistika
                  </button>
               </div>
            </div>
          </div>
        </div>
        <div className="flex gap-3">
          <button onClick={handleAudioGuide} disabled={isGeneratingAudio} className={`flex items-center gap-2 px-4 py-2 rounded-2xl transition-all font-bold text-sm ${isPlayingAudio ? 'bg-red-50 text-red-600 shadow-red-100 shadow-md' : 'bg-slate-100 text-slate-600 hover:bg-slate-200'} ${isGeneratingAudio ? 'opacity-70 cursor-not-allowed' : ''}`}>
            {isGeneratingAudio ? <Loader2 size={20} className="animate-spin" /> : isPlayingAudio ? <StopCircle size={20} /> : <Volume2 size={20} />}
            <span className="hidden sm:inline">{isPlayingAudio ? 'Sustabdyti' : 'Garsinis gidas'}</span>
          </button>
          <button onClick={() => setIsSettingsOpen(true)} className="p-3 bg-slate-100 text-slate-600 rounded-2xl hover:bg-slate-200 transition-colors"><Settings size={20} /></button>
        </div>
      </header>

      <main className="max-w-7xl mx-auto">
        {currentView === 'calculator' ? (
          <div className="grid grid-cols-1 lg:grid-cols-12 gap-8 animate-in fade-in duration-300">
            <section className="lg:col-span-5 space-y-6">
              <div className="bg-white p-8 rounded-[2rem] shadow-xl shadow-slate-200/50 border border-slate-100">
                <h2 className="text-lg font-bold text-slate-800 mb-6 flex items-center gap-2">
                  <FileText size={20} className="text-indigo-600" /> Įvesti duomenis
                </h2>

                <div className="space-y-5">
                  <div className="space-y-1.5">
                    <label className="text-xs font-bold text-slate-500 uppercase ml-1 flex justify-between">
                      <span>1. Darbuotojas</span>
                      {suggestedCoefficient && <span className="text-[10px] text-indigo-500 lowercase flex items-center gap-1"><History size={10}/> istorija rasta</span>}
                    </label>
                    <div className="relative">
                      <User className="absolute left-4 top-1/2 -translate-y-1/2 text-slate-400" size={18} />
                      <input type="text" list="names-list" value={fullName} onChange={e => handleInputChange(setFullName, 'fullName', e.target.value)} placeholder="Vardas Pavardė" className={`w-full pl-12 pr-4 py-3 bg-slate-50 border rounded-2xl outline-none transition-all focus:ring-4 ${errors.fullName ? 'border-red-300 focus:ring-red-50' : 'border-slate-100 focus:ring-indigo-50'}`} />
                      <datalist id="names-list">{historyData.names.map(n => <option key={n} value={n} />)}</datalist>
                    </div>
                    {errors.fullName && <p className="text-[10px] text-red-500 font-bold uppercase ml-1">{errors.fullName}</p>}
                  </div>

                  <div className="space-y-1.5">
                    <label className="text-xs font-bold text-slate-500 uppercase ml-1">2. Pareigos</label>
                    <div className="relative">
                      <Briefcase className="absolute left-4 top-1/2 -translate-y-1/2 text-slate-400" size={18} />
                      <input type="text" list="positions-list" value={position} onChange={e => handleInputChange(setPosition, 'position', e.target.value)} placeholder="Pvz.: Mokytojas" className={`w-full pl-12 pr-4 py-3 bg-slate-50 border rounded-2xl outline-none transition-all focus:ring-4 ${errors.position ? 'border-red-300 focus:ring-red-50' : 'border-slate-100 focus:ring-indigo-50'}`} />
                      <datalist id="positions-list">{historyData.positions.map(p => <option key={p} value={p} />)}</datalist>
                    </div>
                    {errors.position && <p className="text-[10px] text-red-500 font-bold uppercase ml-1">{errors.position}</p>}
                  </div>

                  <div className="space-y-1.5">
                    <label className="text-xs font-bold text-slate-500 uppercase ml-1">3. Savaitės norma</label>
                    <div className="grid grid-cols-2 gap-3">
                      {[WorkloadType.H36, WorkloadType.H40].map(t => (
                        <button key={t} onClick={() => setWorkloadType(t)} className={`py-3 rounded-2xl border-2 font-bold text-sm transition-all ${workloadType === t ? 'border-indigo-600 bg-indigo-50 text-indigo-700' : 'border-slate-50 bg-slate-50 text-slate-400'}`}>
                          {t === WorkloadType.H36 ? '36 val.' : '40 val.'}
                        </button>
                      ))}
                    </div>
                  </div>

                  <div className="grid grid-cols-2 gap-4">
                    <div className="space-y-1.5">
                      <div className="flex justify-between items-end">
                        <label className="text-xs font-bold text-slate-500 uppercase ml-1">Koeficientas</label>
                        {suggestedCoefficient && <button onClick={() => setBaseCoef(suggestedCoefficient.toString())} className="text-[9px] font-black text-indigo-600 bg-indigo-50 px-1.5 py-0.5 rounded hover:bg-indigo-100 transition-colors uppercase">Įkelti {suggestedCoefficient}</button>}
                      </div>
                      <input type="number" list="coefs-list" step="0.0001" value={baseCoef} onChange={e => setBaseCoef(e.target.value)} className="w-full p-3 bg-slate-50 border border-slate-100 rounded-2xl font-mono font-bold outline-none focus:ring-2 focus:ring-indigo-50" />
                      <datalist id="coefs-list">{historyData.coefficients.map(c => <option key={c} value={c} />)}</datalist>
                    </div>
                    <div className="space-y-1.5">
                      <label className="text-xs font-bold text-slate-500 uppercase ml-1">Fakt. valandos</label>
                      <div className="relative">
                        <Clock className="absolute left-3 top-1/2 -translate-y-1/2 text-slate-400" size={16} />
                        <input type="number" step="0.1" value={actualHours} onChange={e => handleInputChange(setActualHours, 'actualHours', e.target.value)} placeholder="0" className={`w-full pl-9 pr-3 py-3 bg-slate-50 border rounded-2xl font-bold outline-none transition-all focus:ring-4 ${errors.actualHours ? 'border-red-300 focus:ring-red-50' : 'border-slate-100 focus:ring-indigo-50'}`} />
                      </div>
                    </div>
                  </div>

                  <div className="space-y-1.5">
                    <label className="text-xs font-bold text-slate-500 uppercase ml-1 flex items-center gap-1"><CalendarDays size={14} className="text-indigo-600" /> 4. Kiek dienų dirbo?</label>
                    <input type="number" value={workedDays} onChange={e => handleInputChange(setWorkedDays, 'workedDays', e.target.value)} className={`w-full p-3 bg-indigo-50/30 border rounded-2xl font-bold outline-none focus:ring-4 ${errors.workedDays ? 'border-red-300 focus:ring-red-50' : 'border-indigo-100 focus:ring-indigo-100'}`} />
                    {errors.workedDays && <p className="text-[10px] text-red-500 font-bold uppercase ml-1">{errors.workedDays}</p>}
                  </div>

                  <button onClick={handleSave} className="w-full py-4 bg-indigo-600 text-white rounded-2xl font-bold shadow-lg shadow-indigo-100 hover:bg-indigo-700 transition-all transform active:scale-[0.98] flex items-center justify-center gap-2"><Save size={20} /> Išsaugoti įrašą</button>
                </div>
              </div>

              {/* Naudingos nuorodos blokas */}
              <div className="bg-white p-6 rounded-[2rem] border border-slate-100 shadow-sm">
                 <h3 className="text-xs font-black text-slate-400 uppercase tracking-widest mb-4 flex items-center gap-2">
                    <BookMarked size={14} className="text-indigo-600" /> Naudingos nuorodos
                 </h3>
                 <div className="grid grid-cols-1 gap-2">
                    <a href="https://www.e-tar.lt/portal/lt/legalAct/8253c29006c711ee9978886e85107ab2/asr" target="_blank" rel="noopener noreferrer" className="flex items-center justify-between p-3 bg-slate-50 rounded-xl hover:bg-indigo-50 hover:text-indigo-700 transition-all group">
                       <span className="text-[10px] font-bold">Bazinio dydžio įstatymas</span>
                       <ExternalLink size={12} className="text-slate-300 group-hover:text-indigo-500" />
                    </a>
                    <a href="https://sodra.lt/statistika/pagrindiniai-socialiniai-rodikliai" target="_blank" rel="noopener noreferrer" className="flex items-center justify-between p-3 bg-slate-50 rounded-xl hover:bg-indigo-50 hover:text-indigo-700 transition-all group">
                       <span className="text-[10px] font-bold">Socialiniai rodikliai („Sodra“)</span>
                       <ExternalLink size={12} className="text-slate-300 group-hover:text-indigo-500" />
                    </a>
                    <a href="https://www.tagidas.lt/savadai/9002/" target="_blank" rel="noopener noreferrer" className="flex items-center justify-between p-3 bg-slate-50 rounded-xl hover:bg-indigo-50 hover:text-indigo-700 transition-all group">
                       <span className="text-[10px] font-bold">Metiniai darbo laiko vidurkiai</span>
                       <ExternalLink size={12} className="text-slate-300 group-hover:text-indigo-500" />
                    </a>
                 </div>
              </div>
            </section>

            <section className="lg:col-span-7 space-y-6">
              <div className="grid grid-cols-1 md:grid-cols-2 gap-6">
                <div className="bg-sheet-orange/10 p-8 rounded-[2rem] border border-orange-200 shadow-sm text-center">
                  <span className="text-xs font-black uppercase text-orange-900/40 block mb-2 tracking-widest">Priemoka</span>
                  <span className="text-4xl font-black text-slate-900">{formatCurrency(supplement)}</span>
                </div>
                <div className="bg-sheet-cyan/10 p-8 rounded-[2rem] border border-cyan-200 shadow-sm text-center">
                  <span className="text-xs font-black uppercase text-cyan-900/40 block mb-2 tracking-widest">Vid. etatas/d.</span>
                  <span className="text-4xl font-black text-slate-900">{formatNumber(dailyFte, 2)}</span>
                </div>
              </div>

              <div className="bg-white rounded-[2rem] shadow-xl shadow-slate-200/50 border border-slate-100 overflow-hidden">
                <div className="p-6 border-b border-slate-50 flex justify-between items-center bg-slate-50/30">
                  <h3 className="font-bold text-slate-800 flex items-center gap-2"><Table size={20} className="text-indigo-600" /> Istorija</h3>
                  <button onClick={handleExportCsv} className="flex items-center gap-2 text-xs font-bold text-indigo-600 bg-white px-4 py-2 rounded-xl border border-indigo-100 hover:bg-indigo-50 transition-all"><Download size={16} /> CSV</button>
                </div>
                <div className="overflow-x-auto">
                  <table className="w-full text-left">
                    <thead className="bg-slate-50/50 text-[10px] font-bold text-slate-400 uppercase tracking-wider">
                      <tr><th className="px-6 py-4">Darbuotojas</th><th className="px-4 py-4 text-center">Koef.</th><th className="px-4 py-4 text-center">Val/D.</th><th className="px-4 py-4 text-center">Etatas</th><th className="px-4 py-4 text-right">Suma</th><th className="px-6 py-4"></th></tr>
                    </thead>
                    <tbody className="divide-y divide-slate-50">
                      {filteredEntries.map(e => (
                        <tr key={e.id} className="hover:bg-slate-50/80 transition-colors group">
                          <td className="px-6 py-4"><div className="text-sm font-bold text-slate-800 mb-0.5">{e.fullName}</div><div className="text-[10px] font-bold text-slate-400 uppercase">{e.position}</div></td>
                          <td className="px-4 py-4 text-center text-xs font-mono font-bold text-slate-600">{formatNumber(e.finalCoefficient, 4)}</td>
                          <td className="px-4 py-4 text-center"><div className="text-xs font-bold text-slate-700">{e.actualHours} val.</div><div className="text-[9px] text-slate-400">{e.workedDays} d.</div></td>
                          <td className="px-4 py-4 text-center"><span className="text-xs font-black text-cyan-600">{formatNumber(e.dailyFte, 2)}</span></td>
                          <td className="px-4 py-4 text-right"><span className="bg-indigo-50 text-indigo-700 px-3 py-1 rounded-full font-extrabold text-xs">{formatCurrency(e.salarySupplement)}</span></td>
                          <td className="px-6 py-4 text-right"><button onClick={() => setDeleteId(e.id)} className="p-2 text-slate-200 hover:text-red-500 rounded-lg transition-all"><Trash2 size={16}/></button></td>
                        </tr>
                      ))}
                      {filteredEntries.length === 0 && <tr><td colSpan={6} className="px-6 py-16 text-center text-slate-400 italic text-sm">Nėra įrašų</td></tr>}
                    </tbody>
                  </table>
                </div>
              </div>
            </section>
          </div>
        ) : (
          <StatisticsView entries={entries} />
        )}
      </main>

      <SettingsModal isOpen={isSettingsOpen} onClose={() => setIsSettingsOpen(false)} config={config} onSave={setConfig} onClearData={() => {
        setEntries([]);
        localStorage.removeItem(STORAGE_KEY_ENTRIES);
      }} />
      <DeleteConfirmationModal isOpen={!!deleteId} onClose={() => setDeleteId(null)} onConfirm={confirmDelete} />
    </div>
  );
};

export default App;

import React, { useState, useMemo, useEffect, useRef } from 'react';
import { 
  Save, Trash2, Settings, FileText, Calculator, Volume2, 
  StopCircle, Loader2, User, Briefcase, Clock, Percent, 
  Table, Search, Filter, XCircle, Download, Eraser, Info,
  ChevronRight, CalendarDays, History, TrendingUp, LayoutGrid,
  ExternalLink, BookMarked
} from 'lucide-react';
import { GoogleGenAI, Modality } from "@google/genai";
import { WorkloadType, Config, CalculationEntry } from './types.ts';
import { 
  calculateFinalCoefficient, 
  calculateSupplement, 
  calculateDailyFte, 
  formatCurrency, 
  formatNumber 
} from './utils/calculations.ts';
import SettingsModal from './components/SettingsModal.tsx';
import DeleteConfirmationModal from './components/DeleteConfirmationModal.tsx';
import Tooltip from './components/Tooltip.tsx';
import StatisticsView from './components/StatisticsView.tsx';

const STORAGE_KEY_ENTRIES = 'priemokos_entries_v2';
const STORAGE_KEY_CONFIG = 'priemokos_config_v2';

const App: React.FC = () => {
  const [currentView, setCurrentView] = useState<'calculator' | 'stats'>('calculator');
  const [config, setConfig] = useState<Config>(() => {
    try {
      const saved = localStorage.getItem(STORAGE_KEY_CONFIG);
      return saved ? JSON.parse(saved) : {
        bma: 1798.00,
        avgHours36: 150.48,
        avgHours40: 166.83
      };
    } catch {
      return { bma: 1798.00, avgHours36: 150.48, avgHours40: 166.83 };
    }
  });

  const [entries, setEntries] = useState<CalculationEntry[]>(() => {
    try {
      const saved = localStorage.getItem(STORAGE_KEY_ENTRIES);
      return saved ? JSON.parse(saved) : [];
    } catch {
      return [];
    }
  });

  const [isSettingsOpen, setIsSettingsOpen] = useState(false);
  const [deleteId, setDeleteId] = useState<string | null>(null);
  const [isPlayingAudio, setIsPlayingAudio] = useState(false);
  const [isGeneratingAudio, setIsGeneratingAudio] = useState(false);
  const audioContextRef = useRef<AudioContext | null>(null);
  const sourceNodeRef = useRef<AudioBufferSourceNode | null>(null);

  const [filterName, setFilterName] = useState('');
  const [filterPosition, setFilterPosition] = useState('');

  const [position, setPosition] = useState('');
  const [fullName, setFullName] = useState('');
  const [workloadType, setWorkloadType] = useState<WorkloadType>(WorkloadType.H36);
  const [baseCoef, setBaseCoef] = useState<string>('1.0000');
  const [increasePercent, setIncreasePercent] = useState<string>('0');
  const [actualHours, setActualHours] = useState<string>('');
  const [workedDays, setWorkedDays] = useState<string>('1'); 
  const [errors, setErrors] = useState<Record<string, string>>({});

  const historyData = useMemo(() => {
    const positions = new Set<string>();
    const names = new Set<string>();
    const coefficients = new Set<string>();

    entries.forEach(e => {
      if (e.position) positions.add(e.position.trim());
      if (e.fullName) names.add(e.fullName.trim());
      if (e.baseCoefficient) coefficients.add(e.baseCoefficient.toString());
    });

    return {
      positions: Array.from(positions).sort(),
      names: Array.from(names).sort(),
      coefficients: Array.from(coefficients).sort((a, b) => parseFloat(b) - parseFloat(a))
    };
  }, [entries]);

  const suggestedCoefficient = useMemo(() => {
    if (!fullName.trim()) return null;
    const lastEntry = entries.find(e => e.fullName.toLowerCase() === fullName.trim().toLowerCase());
    return lastEntry ? lastEntry.baseCoefficient : null;
  }, [fullName, entries]);

  useEffect(() => {
    localStorage.setItem(STORAGE_KEY_ENTRIES, JSON.stringify(entries));
    localStorage.setItem(STORAGE_KEY_CONFIG, JSON.stringify(config));
  }, [entries, config]);

  const parsedBaseCoef = parseFloat(baseCoef) || 0;
  const parsedIncrease = parseFloat(increasePercent) || 0;
  const parsedActualHours = parseFloat(actualHours) || 0;
  const parsedWorkedDays = parseFloat(workedDays) || 1;

  const avgMonthlyHours = workloadType === WorkloadType.H36 ? config.avgHours36 : config.avgHours40;
  const finalCoefficient = useMemo(() => calculateFinalCoefficient(parsedBaseCoef, parsedIncrease), [parsedBaseCoef, parsedIncrease]);
  const supplement = useMemo(() => calculateSupplement(finalCoefficient, config.bma, avgMonthlyHours, parsedActualHours), [finalCoefficient, config.bma, avgMonthlyHours, parsedActualHours]);
  const dailyFte = useMemo(() => calculateDailyFte(parsedActualHours, workloadType, parsedWorkedDays), [parsedActualHours, workloadType, parsedWorkedDays]);

  const filteredEntries = useMemo(() => {
    return entries.filter(entry => {
      const matchesName = entry.fullName.toLowerCase().includes(filterName.toLowerCase());
      const matchesPosition = entry.position.toLowerCase().includes(filterPosition.toLowerCase());
      return matchesName && matchesPosition;
    });
  }, [entries, filterName, filterPosition]);

  const handleInputChange = (setter: (v: string) => void, field: string, value: string) => {
    setter(value);
    if (errors[field]) {
      const newErrors = { ...errors };
      delete newErrors[field];
      setErrors(newErrors);
    }
  };

  const resetForm = () => {
    setPosition('');
    setFullName('');
    setActualHours('');
    setWorkedDays('1');
    setErrors({});
  };

  const handleSave = () => {
    const newErrors: Record<string, string> = {};
    if (!position.trim()) newErrors.position = "Prašome įvesti pareigas";
    if (!fullName.trim()) newErrors.fullName = "Prašome įvesti vardą ir pavardę";
    const h = parseFloat(actualHours);
    if (!actualHours.trim()) newErrors.actualHours = "Įveskite valandas";
    else if (isNaN(h) || h <= 0) newErrors.actualHours = "Neteisingas valandų skaičius";
    const d = parseFloat(workedDays);
    if (!workedDays.trim()) newErrors.workedDays = "Įveskite dienas";
    else if (isNaN(d) || d <= 0) newErrors.workedDays = "Neteisingas dienų skaičius";

    if (Object.keys(newErrors).length > 0) {
      setErrors(newErrors);
      return;
    }

    const newEntry: CalculationEntry = {
      id: Date.now().toString(),
      position: position.trim(),
      fullName: fullName.trim(),
      workloadType,
      baseCoefficient: parsedBaseCoef,
      increasePercent: parsedIncrease,
      finalCoefficient,
      actualHours: parsedActualHours,
      workedDays: parsedWorkedDays,
      salarySupplement: supplement,
      dailyFte,
      dateCreated: new Date().toISOString()
    };

    setEntries([newEntry, ...entries]);
    resetForm();
  };

  const confirmDelete = () => {
    if (deleteId) {
      setEntries(entries.filter(i => i.id !== deleteId));
      setDeleteId(null);
    }
  };

  const handleExportCsv = () => {
    if (filteredEntries.length === 0) return;
    const headers = ['Vardas Pavardė', 'Pareigos', 'Režimas', 'Koef.', 'Valandos', 'Dienos', 'Suma', 'Etatas/d.'];
    const rows = filteredEntries.map(e => [
      `"${e.fullName}"`, `"${e.position}"`, e.workloadType === WorkloadType.H36 ? '36h' : '40h',
      formatNumber(e.finalCoefficient, 4).replace(',', '.'), formatNumber(e.actualHours, 1).replace(',', '.'),
      e.workedDays || '', formatNumber(e.salarySupplement, 2).replace(',', '.'), formatNumber(e.dailyFte, 2).replace(',', '.')
    ]);
    const csvContent = headers.join(',') + '\n' + rows.map(r => r.join(',')).join('\n');
    const blob = new Blob(['\ufeff' + csvContent], { type: 'text/csv;charset=utf-8;' });
    const url = URL.createObjectURL(blob);
    const link = document.createElement('a');
    link.href = url;
    link.download = `priemokos_${new Date().toISOString().split('T')[0]}.csv`;
    link.click();
  };

  const decodeBase64 = (base64: string) => {
    const binaryString = window.atob(base64);
    const bytes = new Uint8Array(binaryString.length);
    for (let i = 0; i < binaryString.length; i++) bytes[i] = binaryString.charCodeAt(i);
    return bytes;
  };

  const decodeAudioData = async (data: Uint8Array, ctx: AudioContext, sampleRate: number, numChannels: number): Promise<AudioBuffer> => {
    const dataInt16 = new Int16Array(data.buffer, data.byteOffset, data.byteLength / 2);
    const frameCount = dataInt16.length / numChannels;
    const buffer = ctx.createBuffer(numChannels, frameCount, sampleRate);
    for (let ch = 0; ch < numChannels; ch++) {
      const chData = buffer.getChannelData(ch);
      for (let i = 0; i < frameCount; i++) chData[i] = dataInt16[i * numChannels + ch] / 32768.0;
    }
    return buffer;
  };

  const handleAudioGuide = async () => {
    if (isPlayingAudio) { 
      if (sourceNodeRef.current) {
        try { sourceNodeRef.current.stop(); } catch(e) {}
      }
      setIsPlayingAudio(false); 
      return; 
    }

    setIsGeneratingAudio(true);
    try {
      if (!audioContextRef.current) {
        audioContextRef.current = new (window.AudioContext || (window as any).webkitAudioContext)({ sampleRate: 24000 });
      }
      if (audioContextRef.current.state === 'suspended') {
        await audioContextRef.current.resume();
      }

      const ai = new GoogleGenAI({ apiKey: process.env.API_KEY });
      const prompt = currentView === 'calculator' 
        ? "Esate skaičiuoklės skiltyje. Čia galite suvesti darbuotojo vardą, pareigas, koeficientą bei dirbtas valandas. Paspaudę išsaugoti, matysite apskaičiuotą priemoką istorijos lentelėje."
        : "Esate statistikos skiltyje. Čia galite matyti bendrą priemokų sumą, darbuotojų skaičių bei išmokų pasiskirstymą pagal pareigas.";

      const response = await ai.models.generateContent({
        model: 'gemini-2.5-flash-preview-tts',
        contents: [{ parts: [{ text: prompt }] }],
        config: { 
          responseModalities: [Modality.AUDIO], 
          speechConfig: { 
            voiceConfig: { 
              prebuiltVoiceConfig: { voiceName: 'Kore' } 
            } 
          } 
        },
      });

      const b64 = response.candidates?.[0]?.content?.parts?.[0]?.inlineData?.data;
      if (!b64) throw new Error("Nepavyko gauti garso duomenų");

      const buffer = await decodeAudioData(decodeBase64(b64), audioContextRef.current, 24000, 1);
      const source = audioContextRef.current.createBufferSource();
      source.buffer = buffer;
      source.connect(audioContextRef.current.destination);
      source.onended = () => {
        setIsPlayingAudio(false);
        sourceNodeRef.current = null;
      };
      sourceNodeRef.current = source;
      source.start();
      setIsPlayingAudio(true);
    } catch (e) { 
      console.error("Audio Guide Error:", e);
      alert("Atsiprašome, nepavyko paleisti audio gido. Patikrinkite interneto ryšį.");
    } finally { 
      setIsGeneratingAudio(false); 
    }
  };

  return (
    <div className="min-h-screen bg-slate-50 p-4 md:p-8">
      <header className="max-w-7xl mx-auto flex flex-col md:flex-row justify-between items-center mb-8 bg-white p-6 rounded-3xl shadow-sm border border-slate-100 gap-4">
        <div className="flex items-center gap-4">
          <div className="bg-indigo-600 p-3 rounded-2xl text-white shadow-indigo-100 shadow-xl">
            <Calculator size={28} />
          </div>
          <div>
            <h1 className="text-2xl font-extrabold text-slate-900 tracking-tight">Priemokų skaičiuoklė 2026</h1>
            <div className="flex gap-4 mt-1">
               <p className="text-[10px] font-bold text-slate-400 uppercase tracking-widest">BD: {formatCurrency(config.bma)}</p>
               <div className="flex bg-slate-100 p-1 rounded-lg">
                  <button 
                    onClick={() => setCurrentView('calculator')}
                    className={`px-3 py-1 rounded-md text-[10px] font-bold uppercase tracking-wider transition-all flex items-center gap-1.5 ${currentView === 'calculator' ? 'bg-white text-indigo-600 shadow-sm' : 'text-slate-400 hover:text-slate-600'}`}
                  >
                    <LayoutGrid size={12} /> Skaičiuoklė
                  </button>
                  <button 
                    onClick={() => setCurrentView('stats')}
                    className={`px-3 py-1 rounded-md text-[10px] font-bold uppercase tracking-wider transition-all flex items-center gap-1.5 ${currentView === 'stats' ? 'bg-white text-indigo-600 shadow-sm' : 'text-slate-400 hover:text-slate-600'}`}
                  >
                    <TrendingUp size={12} /> Statistika
                  </button>
               </div>
            </div>
          </div>
        </div>
        <div className="flex gap-3">
          <button onClick={handleAudioGuide} disabled={isGeneratingAudio} className={`flex items-center gap-2 px-4 py-2 rounded-2xl transition-all font-bold text-sm ${isPlayingAudio ? 'bg-red-50 text-red-600 shadow-red-100 shadow-md' : 'bg-slate-100 text-slate-600 hover:bg-slate-200'} ${isGeneratingAudio ? 'opacity-70 cursor-not-allowed' : ''}`}>
            {isGeneratingAudio ? <Loader2 size={20} className="animate-spin" /> : isPlayingAudio ? <StopCircle size={20} /> : <Volume2 size={20} />}
            <span className="hidden sm:inline">{isPlayingAudio ? 'Sustabdyti' : 'Garsinis gidas'}</span>
          </button>
          <button onClick={() => setIsSettingsOpen(true)} className="p-3 bg-slate-100 text-slate-600 rounded-2xl hover:bg-slate-200 transition-colors"><Settings size={20} /></button>
        </div>
      </header>

      <main className="max-w-7xl mx-auto">
        {currentView === 'calculator' ? (
          <div className="grid grid-cols-1 lg:grid-cols-12 gap-8 animate-in fade-in duration-300">
            <section className="lg:col-span-5 space-y-6">
              <div className="bg-white p-8 rounded-[2rem] shadow-xl shadow-slate-200/50 border border-slate-100">
                <h2 className="text-lg font-bold text-slate-800 mb-6 flex items-center gap-2">
                  <FileText size={20} className="text-indigo-600" /> Įvesti duomenis
                </h2>

                <div className="space-y-5">
                  <div className="space-y-1.5">
                    <label className="text-xs font-bold text-slate-500 uppercase ml-1 flex justify-between">
                      <span>Vardas, Pavardė</span>
                      {suggestedCoefficient && <span className="text-[10px] text-indigo-500 lowercase flex items-center gap-1"><History size={10}/> istorija rasta</span>}
                    </label>
                    <div className="relative">
                      <User className="absolute left-4 top-1/2 -translate-y-1/2 text-slate-400" size={18} />
                      <input type="text" list="names-list" value={fullName} onChange={e => handleInputChange(setFullName, 'fullName', e.target.value)} placeholder="Vardas Pavardė" className={`w-full pl-12 pr-4 py-3 bg-slate-50 border rounded-2xl outline-none transition-all focus:ring-4 ${errors.fullName ? 'border-red-300 focus:ring-red-50' : 'border-slate-100 focus:ring-indigo-50'}`} />
                      <datalist id="names-list">{historyData.names.map(n => <option key={n} value={n} />)}</datalist>
                    </div>
                    {errors.fullName && <p className="text-[10px] text-red-500 font-bold uppercase ml-1">{errors.fullName}</p>}
                  </div>

                  <div className="space-y-1.5">
                    <label className="text-xs font-bold text-slate-500 uppercase ml-1">Pareigos</label>
                    <div className="relative">
                      <Briefcase className="absolute left-4 top-1/2 -translate-y-1/2 text-slate-400" size={18} />
                      <input type="text" list="positions-list" value={position} onChange={e => handleInputChange(setPosition, 'position', e.target.value)} placeholder="Pvz.: Mokytojas" className={`w-full pl-12 pr-4 py-3 bg-slate-50 border rounded-2xl outline-none transition-all focus:ring-4 ${errors.position ? 'border-red-300 focus:ring-red-50' : 'border-slate-100 focus:ring-indigo-50'}`} />
                      <datalist id="positions-list">{historyData.positions.map(p => <option key={p} value={p} />)}</datalist>
                    </div>
                    {errors.position && <p className="text-[10px] text-red-500 font-bold uppercase ml-1">{errors.position}</p>}
                  </div>

                  <div className="space-y-1.5">
                    <label className="text-xs font-bold text-slate-500 uppercase ml-1">Savaitės norma</label>
                    <div className="grid grid-cols-2 gap-3">
                      {[WorkloadType.H36, WorkloadType.H40].map(t => (
                        <button key={t} onClick={() => setWorkloadType(t)} className={`py-3 rounded-2xl border-2 font-bold text-sm transition-all ${workloadType === t ? 'border-indigo-600 bg-indigo-50 text-indigo-700' : 'border-slate-50 bg-slate-50 text-slate-400'}`}>
                          {t === WorkloadType.H36 ? '36 val.' : '40 val.'}
                        </button>
                      ))}
                    </div>
                  </div>

                  <div className="grid grid-cols-2 gap-4">
                    <div className="space-y-1.5">
                      <div className="flex justify-between items-end">
                        <label className="text-xs font-bold text-slate-500 uppercase ml-1">Pareiginės algos koeficientas</label>
                        {suggestedCoefficient && <button onClick={() => setBaseCoef(suggestedCoefficient.toString())} className="text-[9px] font-black text-indigo-600 bg-indigo-50 px-1.5 py-0.5 rounded hover:bg-indigo-100 transition-colors uppercase">Įkelti {suggestedCoefficient}</button>}
                      </div>
                      <input type="number" list="coefs-list" step="0.0001" value={baseCoef} onChange={e => setBaseCoef(e.target.value)} className="w-full p-3 bg-slate-50 border border-slate-100 rounded-2xl font-mono font-bold outline-none focus:ring-2 focus:ring-indigo-50" />
                      <datalist id="coefs-list">{historyData.coefficients.map(c => <option key={c} value={c} />)}</datalist>
                    </div>
                    <div className="space-y-1.5">
                      <label className="text-xs font-bold text-slate-500 uppercase ml-1">Faktiškai dirbtos valandos</label>
                      <div className="relative">
                        <Clock className="absolute left-3 top-1/2 -translate-y-1/2 text-slate-400" size={16} />
                        <input type="number" step="0.1" value={actualHours} onChange={e => handleInputChange(setActualHours, 'actualHours', e.target.value)} placeholder="0" className={`w-full pl-9 pr-3 py-3 bg-slate-50 border rounded-2xl font-bold outline-none transition-all focus:ring-4 ${errors.actualHours ? 'border-red-300 focus:ring-red-50' : 'border-slate-100 focus:ring-indigo-50'}`} />
                      </div>
                    </div>
                  </div>

                  <div className="space-y-1.5">
                    <label className="text-xs font-bold text-slate-500 uppercase ml-1 flex items-center gap-1"><CalendarDays size={14} className="text-indigo-600" /> Kiek dienų dirbo?</label>
                    <input type="number" value={workedDays} onChange={e => handleInputChange(setWorkedDays, 'workedDays', e.target.value)} className={`w-full p-3 bg-indigo-50/30 border rounded-2xl font-bold outline-none focus:ring-4 ${errors.workedDays ? 'border-red-300 focus:ring-red-50' : 'border-indigo-100 focus:ring-indigo-100'}`} />
                    {errors.workedDays && <p className="text-[10px] text-red-500 font-bold uppercase ml-1">{errors.workedDays}</p>}
                  </div>

                  <button onClick={handleSave} className="w-full py-4 bg-indigo-600 text-white rounded-2xl font-bold shadow-lg shadow-indigo-100 hover:bg-indigo-700 transition-all transform active:scale-[0.98] flex items-center justify-center gap-2"><Save size={20} /> Išsaugoti įrašą</button>
                </div>
              </div>

              {/* Naudingos nuorodos blokas */}
              <div className="bg-white p-6 rounded-[2rem] border border-slate-100 shadow-sm">
                 <h3 className="text-xs font-black text-slate-400 uppercase tracking-widest mb-4 flex items-center gap-2">
                    <BookMarked size={14} className="text-indigo-600" /> Naudingos nuorodos
                 </h3>
                 <div className="grid grid-cols-1 gap-2">
                    <a href="https://www.e-tar.lt/portal/lt/legalAct/8253c29006c711ee9978886e85107ab2/asr" target="_blank" rel="noopener noreferrer" className="flex items-center justify-between p-3 bg-slate-50 rounded-xl hover:bg-indigo-50 hover:text-indigo-700 transition-all group">
                       <span className="text-[10px] font-bold">Bazinio dydžio įstatymas</span>
                       <ExternalLink size={12} className="text-slate-300 group-hover:text-indigo-500" />
                    </a>
                    <a href="https://sodra.lt/statistika/pagrindiniai-socialiniai-rodikliai" target="_blank" rel="noopener noreferrer" className="flex items-center justify-between p-3 bg-slate-50 rounded-xl hover:bg-indigo-50 hover:text-indigo-700 transition-all group">
                       <span className="text-[10px] font-bold">Socialiniai rodikliai („Sodra“)</span>
                       <ExternalLink size={12} className="text-slate-300 group-hover:text-indigo-500" />
                    </a>
                    <a href="https://www.tagidas.lt/savadai/9002/" target="_blank" rel="noopener noreferrer" className="flex items-center justify-between p-3 bg-slate-50 rounded-xl hover:bg-indigo-50 hover:text-indigo-700 transition-all group">
                       <span className="text-[10px] font-bold">Metiniai darbo laiko vidurkiai</span>
                       <ExternalLink size={12} className="text-slate-300 group-hover:text-indigo-500" />
                    </a>
                 </div>
              </div>
            </section>

            <section className="lg:col-span-7 space-y-6">
              <div className="grid grid-cols-1 md:grid-cols-2 gap-6">
                <div className="bg-sheet-orange/10 p-8 rounded-[2rem] border border-orange-200 shadow-sm text-center">
                  <span className="text-xs font-black uppercase text-orange-900/40 block mb-2 tracking-widest">Priemoka</span>
                  <span className="text-4xl font-black text-slate-900">{formatCurrency(supplement)}</span>
                </div>
                <div className="bg-sheet-cyan/10 p-8 rounded-[2rem] border border-cyan-200 shadow-sm text-center">
                  <span className="text-xs font-black uppercase text-cyan-900/40 block mb-2 tracking-widest">Vid. etatas/d.</span>
                  <span className="text-4xl font-black text-slate-900">{formatNumber(dailyFte, 2)}</span>
                </div>
              </div>

              <div className="bg-white rounded-[2rem] shadow-xl shadow-slate-200/50 border border-slate-100 overflow-hidden">
                <div className="p-6 border-b border-slate-50 flex justify-between items-center bg-slate-50/30">
                  <h3 className="font-bold text-slate-800 flex items-center gap-2"><Table size={20} className="text-indigo-600" /> Istorija</h3>
                  <button onClick={handleExportCsv} className="flex items-center gap-2 text-xs font-bold text-indigo-600 bg-white px-4 py-2 rounded-xl border border-indigo-100 hover:bg-indigo-50 transition-all"><Download size={16} /> CSV</button>
                </div>
                <div className="overflow-x-auto">
                  <table className="w-full text-left">
                    <thead className="bg-slate-50/50 text-[10px] font-bold text-slate-400 uppercase tracking-wider">
                      <tr><th className="px-6 py-4">Darbuotojas</th><th className="px-4 py-4 text-center">Koef.</th><th className="px-4 py-4 text-center">Val/D.</th><th className="px-4 py-4 text-center">Etatas</th><th className="px-4 py-4 text-right">Suma</th><th className="px-6 py-4"></th></tr>
                    </thead>
                    <tbody className="divide-y divide-slate-50">
                      {filteredEntries.map(e => (
                        <tr key={e.id} className="hover:bg-slate-50/80 transition-colors group">
                          <td className="px-6 py-4"><div className="text-sm font-bold text-slate-800 mb-0.5">{e.fullName}</div><div className="text-[10px] font-bold text-slate-400 uppercase">{e.position}</div></td>
                          <td className="px-4 py-4 text-center text-xs font-mono font-bold text-slate-600">{formatNumber(e.finalCoefficient, 4)}</td>
                          <td className="px-4 py-4 text-center"><div className="text-xs font-bold text-slate-700">{e.actualHours} val.</div><div className="text-[9px] text-slate-400">{e.workedDays} d.</div></td>
                          <td className="px-4 py-4 text-center"><span className="text-xs font-black text-cyan-600">{formatNumber(e.dailyFte, 2)}</span></td>
                          <td className="px-4 py-4 text-right"><span className="bg-indigo-50 text-indigo-700 px-3 py-1 rounded-full font-extrabold text-xs">{formatCurrency(e.salarySupplement)}</span></td>
                          <td className="px-6 py-4 text-right"><button onClick={() => setDeleteId(e.id)} className="p-2 text-slate-200 hover:text-red-500 rounded-lg transition-all"><Trash2 size={16}/></button></td>
                        </tr>
                      ))}
                      {filteredEntries.length === 0 && <tr><td colSpan={6} className="px-6 py-16 text-center text-slate-400 italic text-sm">Nėra įrašų</td></tr>}
                    </tbody>
                  </table>
                </div>
              </div>
            </section>
          </div>
        ) : (
          <StatisticsView entries={entries} />
        )}
      </main>

      <SettingsModal isOpen={isSettingsOpen} onClose={() => setIsSettingsOpen(false)} config={config} onSave={setConfig} onClearData={() => {
        setEntries([]);
        localStorage.removeItem(STORAGE_KEY_ENTRIES);
      }} />
      <DeleteConfirmationModal isOpen={!!deleteId} onClose={() => setDeleteId(null)} onConfirm={confirmDelete} />
    </div>
  );
};

export default App;

