      url: 'https://sodra.lt/statistika/pagrindiniai-socialiniai-rodikliai',
    },
    {
      title: 'Vidutinio darbo laiko skaičiai (TAGIDAS)',
      url: 'https://www.tagidas.lt/savadai/9002/',
    }
  ];

  return (
    <div className="fixed inset-0 z-50 flex items-center justify-center bg-black/50 backdrop-blur-sm p-4">
      <div className="bg-white rounded-3xl shadow-2xl w-full max-w-md overflow-hidden max-h-[90vh] overflow-y-auto animate-in zoom-in-95 duration-200">
        <div className="bg-slate-100 px-6 py-4 flex justify-between items-center border-b border-slate-200 sticky top-0 z-10">
          <h3 className="text-lg font-bold text-slate-800">Sistemos nustatymai</h3>
          <button onClick={onClose} className="text-slate-500 hover:text-slate-700 transition-colors"><X size={24} /></button>
        </div>

        <div className="p-6 space-y-6">
          {/* Bazinis Dydis */}
          <div>
            <label className="block text-sm font-bold text-slate-700 mb-1">Bazinis dydis (BD)</label>
            <div className="relative">
              <input 
                type="number" 
                step="0.01" 
                value={localConfig.bma} 
                onChange={handleBmaChange} 
                className="w-full px-4 py-3 bg-slate-50 border border-slate-200 rounded-xl focus:ring-4 focus:ring-indigo-50 outline-none font-bold text-indigo-700" 
              />
              <div className="absolute right-4 top-1/2 -translate-y-1/2 text-slate-400 text-sm font-bold">€</div>
            </div>
            <p className="text-[10px] text-slate-400 mt-1 uppercase font-bold tracking-wider">2026 m. patvirtintas: 1798,00 €</p>
          </div>

          <div className="h-px bg-slate-100" />

          {/* Vidutiniai Valandų Skaičiai */}
          <div className="space-y-4">
            <div className="flex items-center justify-between">
              <h4 className="font-bold text-slate-800 text-sm flex items-center gap-2">
                <Calculator size={16} className="text-indigo-600" /> 2026 m. vidutiniai val. skaičiai
              </h4>
              {!canEditHours && (
                <div className="group relative">
                  <span className="flex items-center text-[9px] text-amber-600 bg-amber-50 px-2 py-1 rounded-full font-bold uppercase cursor-help">
                    <Lock size={10} className="mr-1" /> Fiksuota
                  </span>
                  <div className="absolute bottom-full right-0 mb-2 w-48 p-2 bg-slate-800 text-white text-[10px] rounded-lg opacity-0 group-hover:opacity-100 transition-opacity pointer-events-none z-20">
                    Šie rodikliai nustatomi teisės aktais metams. Redaguoti galima tik sausio mėnesį.
                  </div>
                </div>
              )}
            </div>

            <div className="grid grid-cols-2 gap-4">
              <div className="space-y-1">
                <label className="text-[10px] font-black text-slate-400 uppercase tracking-widest ml-1">36 val. norma</label>
                <input 
                  type="number" 
                  step="0.01"
                  disabled={!canEditHours}
                  value={localConfig.avgHours36}
                  onChange={(e) => handleHourChange('avgHours36', e.target.value)}
                  className={`w-full p-3 border rounded-xl font-mono text-sm font-bold ${!canEditHours ? 'bg-slate-50 text-slate-500 border-slate-100' : 'bg-white border-slate-200 text-indigo-600'}`}
                />
                <p className="text-[9px] text-slate-400 italic ml-1">Mokytojams (150.48)</p>
              </div>
              <div className="space-y-1">
                <label className="text-[10px] font-black text-slate-400 uppercase tracking-widest ml-1">40 val. norma</label>
                <input 
                  type="number" 
                  step="0.01"
                  disabled={!canEditHours}
                  value={localConfig.avgHours40}
                  onChange={(e) => handleHourChange('avgHours40', e.target.value)}
                  className={`w-full p-3 border rounded-xl font-mono text-sm font-bold ${!canEditHours ? 'bg-slate-50 text-slate-500 border-slate-100' : 'bg-white border-slate-200 text-indigo-600'}`}
                />
