  ExternalLink, BookMarked, Sparkles, ArrowRight
} from 'lucide-react';
import { GoogleGenAI, Modality } from "@google/genai";
import { WorkloadType, Config, CalculationEntry } from './types.ts';
import { 
  calculateFinalCoefficient, 
  calculateSupplement, 
  calculateDailyFte, 
  formatCurrency, 
  formatNumber 
} from './utils/calculations.ts';
import SettingsModal from './components/SettingsModal.tsx';
import DeleteConfirmationModal from './components/DeleteConfirmationModal.tsx';
import ClearAllConfirmationModal from './components/ClearAllConfirmationModal.tsx';
import Tooltip from './components/Tooltip.tsx';
import StatisticsView from './components/StatisticsView.tsx';

const STORAGE_KEY_ENTRIES = 'priemokos_entries_v2';
const STORAGE_KEY_CONFIG = 'priemokos_config_v2';

const App: React.FC = () => {
  const [currentView, setCurrentView] = useState<'calculator' | 'stats'>('calculator');
  const [config, setConfig] = useState<Config>(() => {
    try {
      const saved = localStorage.getItem(STORAGE_KEY_CONFIG);
      return saved ? JSON.parse(saved) : {
        bma: 1798.00,
        avgHours36: 150.48,
        avgHours40: 166.83
      };
    } catch {
      return { bma: 1798.00, avgHours36: 150.48, avgHours40: 166.83 };
    }
  });

  const [entries, setEntries] = useState<CalculationEntry[]>(() => {
    try {
      const saved = localStorage.getItem(STORAGE_KEY_ENTRIES);
      return saved ? JSON.parse(saved) : [];
    } catch {
      return [];
    }
  });

  const [isSettingsOpen, setIsSettingsOpen] = useState(false);
  const [deleteId, setDeleteId] = useState<string | null>(null);
  const [isClearAllModalOpen, setIsClearAllModalOpen] = useState(false);
  const [isPlayingAudio, setIsPlayingAudio] = useState(false);
  const [isGeneratingAudio, setIsGeneratingAudio] = useState(false);
  const audioContextRef = useRef<AudioContext | null>(null);
  const sourceNodeRef = useRef<AudioBufferSourceNode | null>(null);

  const [filterName, setFilterName] = useState('');
  const [filterPosition, setFilterPosition] = useState('');

  const [position, setPosition] = useState('');
  const [fullName, setFullName] = useState('');
  const [workloadType, setWorkloadType] = useState<WorkloadType>(WorkloadType.H36);
  const [baseCoef, setBaseCoef] = useState<string>('1.0000');
  const [increasePercent, setIncreasePercent] = useState<string>('0');
  const [actualHours, setActualHours] = useState<string>('');
  const [workedDays, setWorkedDays] = useState<string>('1'); 
  const [errors, setErrors] = useState<Record<string, string>>({});

  const historyData = useMemo(() => {
    const positions = new Set<string>();
    const names = new Set<string>();
    const coefficients = new Set<string>();

    entries.forEach(e => {
      if (e.position) positions.add(e.position.trim());
      if (e.fullName) names.add(e.fullName.trim());
      if (e.baseCoefficient) coefficients.add(e.baseCoefficient.toString());
    });

    return {
      positions: Array.from(positions).sort(),
      names: Array.from(names).sort(),
      coefficients: Array.from(coefficients).sort((a, b) => parseFloat(b) - parseFloat(a))
    };
  }, [entries]);

  const suggestedCoefficient = useMemo(() => {
    if (!fullName.trim()) return null;
    const lastEntry = entries.find(e => e.fullName.toLowerCase() === fullName.trim().toLowerCase());
    return lastEntry ? lastEntry.baseCoefficient : null;
  }, [fullName, entries]);

  useEffect(() => {
    localStorage.setItem(STORAGE_KEY_ENTRIES, JSON.stringify(entries));
    localStorage.setItem(STORAGE_KEY_CONFIG, JSON.stringify(config));
  }, [entries, config]);

  const parsedBaseCoef = parseFloat(baseCoef) || 0;
  const parsedIncrease = parseFloat(increasePercent) || 0;
  const parsedActualHours = parseFloat(actualHours) || 0;
  const parsedWorkedDays = parseFloat(workedDays) || 1;

  const avgMonthlyHours = workloadType === WorkloadType.H36 ? config.avgHours36 : config.avgHours40;
  const finalCoefficient = useMemo(() => calculateFinalCoefficient(parsedBaseCoef, parsedIncrease), [parsedBaseCoef, parsedIncrease]);
  const supplement = useMemo(() => calculateSupplement(finalCoefficient, config.bma, avgMonthlyHours, parsedActualHours), [finalCoefficient, config.bma, avgMonthlyHours, parsedActualHours]);
  const dailyFte = useMemo(() => calculateDailyFte(parsedActualHours, workloadType, parsedWorkedDays), [parsedActualHours, workloadType, parsedWorkedDays]);

  const filteredEntries = useMemo(() => {
    return entries.filter(entry => {
      const matchesName = entry.fullName.toLowerCase().includes(filterName.toLowerCase());
      const matchesPosition = entry.position.toLowerCase().includes(filterPosition.toLowerCase());
      return matchesName && matchesPosition;
    });
  }, [entries, filterName, filterPosition]);

  const handleInputChange = (setter: (v: string) => void, field: string, value: string) => {
    setter(value);
    if (errors[field]) {
      const newErrors = { ...errors };
      delete newErrors[field];
      setErrors(newErrors);
    }
  };

  const resetForm = () => {
    setPosition('');
    setFullName('');
    setActualHours('');
    setWorkedDays('1');
    setErrors({});
  };

  const handleSave = () => {
    const newErrors: Record<string, string> = {};
    if (!position.trim()) newErrors.position = "Prašome įvesti pareigas";
    if (!fullName.trim()) newErrors.fullName = "Prašome įvesti vardą ir pavardę";
    const h = parseFloat(actualHours);
    if (!actualHours.trim()) newErrors.actualHours = "Įveskite valandas";
    else if (isNaN(h) || h <= 0) newErrors.actualHours = "Neteisingas valandų skaičius";
    const d = parseFloat(workedDays);
    if (!workedDays.trim()) newErrors.workedDays = "Įveskite dienas";
    else if (isNaN(d) || d <= 0) newErrors.workedDays = "Neteisingas dienų skaičius";

    if (Object.keys(newErrors).length > 0) {
      setErrors(newErrors);
      return;
    }

    const newEntry: CalculationEntry = {
      id: Date.now().toString(),
      position: position.trim(),
      fullName: fullName.trim(),
      workloadType,
      baseCoefficient: parsedBaseCoef,
      increasePercent: parsedIncrease,
      finalCoefficient,
      actualHours: parsedActualHours,
      workedDays: parsedWorkedDays,
      salarySupplement: supplement,
      dailyFte,
      dateCreated: new Date().toISOString()
    };

    setEntries([newEntry, ...entries]);
    resetForm();
  };

  const confirmDelete = () => {
    if (deleteId) {
      setEntries(entries.filter(i => i.id !== deleteId));
      setDeleteId(null);
    }
  };

  const handleClearAll = () => {
    setEntries([]);
    localStorage.removeItem(STORAGE_KEY_ENTRIES);
  };

  const handleExportCsv = () => {
    if (filteredEntries.length === 0) return;
    const headers = ['Vardas Pavardė', 'Pareigos', 'Režimas', 'Koef.', 'Valandos', 'Dienos', 'Suma', 'Etatas/d.'];
    const rows = filteredEntries.map(e => [
      `"${e.fullName}"`, `"${e.position}"`, e.workloadType === WorkloadType.H36 ? '36h' : '40h',
      formatNumber(e.finalCoefficient, 4).replace(',', '.'), formatNumber(e.actualHours, 1).replace(',', '.'),
      e.workedDays || '', formatNumber(e.salarySupplement, 2).replace(',', '.'), formatNumber(e.dailyFte, 2).replace(',', '.')
    ]);
    const csvContent = headers.join(',') + '\n' + rows.map(r => r.join(',')).join('\n');
    const blob = new Blob(['\ufeff' + csvContent], { type: 'text/csv;charset=utf-8;' });
    const url = URL.createObjectURL(blob);
    const link = document.createElement('a');
    link.href = url;
    link.download = `priemokos_${new Date().toISOString().split('T')[0]}.csv`;
    link.click();
  };

  const decodeBase64 = (base64: string) => {
    const binaryString = window.atob(base64);
    const bytes = new Uint8Array(binaryString.length);
    for (let i = 0; i < binaryString.length; i++) bytes[i] = binaryString.charCodeAt(i);
    return bytes;
  };

  const decodeAudioData = async (data: Uint8Array, ctx: AudioContext, sampleRate: number, numChannels: number): Promise<AudioBuffer> => {
    const dataInt16 = new Int16Array(data.buffer, data.byteOffset, data.byteLength / 2);
    const frameCount = dataInt16.length / numChannels;
    const buffer = ctx.createBuffer(numChannels, frameCount, sampleRate);
    for (let ch = 0; ch < numChannels; ch++) {
      const chData = buffer.getChannelData(ch);
      for (let i = 0; i < frameCount; i++) chData[i] = dataInt16[i * numChannels + ch] / 32768.0;
    }
    return buffer;
  };

  const handleAudioGuide = async () => {
    if (isPlayingAudio) { 
      if (sourceNodeRef.current) {
        try { sourceNodeRef.current.stop(); } catch(e) {}
      }
      setIsPlayingAudio(false); 
      return; 
    }

    setIsGeneratingAudio(true);
    try {
      if (!audioContextRef.current) {
        audioContextRef.current = new (window.AudioContext || (window as any).webkitAudioContext)({ sampleRate: 24000 });
      }
      if (audioContextRef.current.state === 'suspended') {
        await audioContextRef.current.resume();
      }

      const ai = new GoogleGenAI({ apiKey: process.env.API_KEY });
      const prompt = currentView === 'calculator' 
        ? "Esate skaičiuoklės skiltyje. Čia galite suvesti darbuotojo vardą, pareigas, koeficientą bei dirbtas valandas. Paspaudę išsaugoti, matysite apskaičiuotą priemoką istorijos lentelėje."
        : "Esate statistikos skiltyje. Čia galite matyti bendrą priemokų sumą, darbuotojų skaičių bei išmokų pasiskirstymą pagal pareigas.";

      const response = await ai.models.generateContent({
        model: 'gemini-2.5-flash-preview-tts',
        contents: [{ parts: [{ text: prompt }] }],
        config: { 
          responseModalities: [Modality.AUDIO], 
          speechConfig: { 
            voiceConfig: { 
              prebuiltVoiceConfig: { voiceName: 'Kore' } 
            } 
          } 
        },
      });

      const b64 = response.candidates?.[0]?.content?.parts?.[0]?.inlineData?.data;
      if (!b64) throw new Error("Nepavyko gauti garso duomenų");

      const buffer = await decodeAudioData(decodeBase64(b64), audioContextRef.current, 24000, 1);
      const source = audioContextRef.current.createBufferSource();
      source.buffer = buffer;
      source.connect(audioContextRef.current.destination);
      source.onended = () => {
        setIsPlayingAudio(false);
        sourceNodeRef.current = null;
      };
      sourceNodeRef.current = source;
      source.start();
      setIsPlayingAudio(true);
    } catch (e) { 
      console.error("Audio Guide Error:", e);
      alert("Atsiprašome, nepavyko paleisti audio gido. Patikrinkite interneto ryšį.");
    } finally { 
      setIsGeneratingAudio(false); 
    }
  };

  return (
    <div className="min-h-screen bg-[#fcfdff] bg-[radial-gradient(ellipse_at_top_right,_var(--tw-gradient-stops))] from-indigo-50/50 via-white to-slate-50 p-4 md:p-12 selection:bg-indigo-100 selection:text-indigo-900">
      <header className="max-w-7xl mx-auto flex flex-col md:flex-row justify-between items-center mb-12 bg-white/80 backdrop-blur-xl p-6 rounded-[2.5rem] shadow-[0_8px_30px_rgb(0,0,0,0.04)] border border-white/40 gap-6">
        <div className="flex items-center gap-5">
          <div className="relative">
            <div className="absolute -inset-1 bg-gradient-to-tr from-indigo-600 to-indigo-400 rounded-2xl blur opacity-25"></div>
            <div className="relative bg-gradient-to-tr from-indigo-600 to-indigo-500 p-4 rounded-2xl text-white shadow-lg shadow-indigo-200">
              <Calculator size={28} />
            </div>
          </div>
          <div>
            <h1 className="text-2xl font-black text-slate-900 tracking-tight flex items-center gap-2">
              Priemokų skaičiuoklė <span className="text-indigo-600 px-3 py-1 bg-indigo-50 rounded-full text-xs font-black">2026</span>
            </h1>
            <div className="flex flex-wrap gap-4 mt-2">
               <div className="flex items-center gap-1.5 text-[10px] font-bold text-slate-400 uppercase tracking-widest bg-slate-50 px-2 py-1 rounded-lg border border-slate-100">
                  <span className="w-1.5 h-1.5 rounded-full bg-indigo-500 animate-pulse"></span>
                  BD: {formatCurrency(config.bma)}
               </div>
               <nav className="flex bg-slate-100/50 p-1 rounded-xl border border-slate-200/50">
                  <button 
                    onClick={() => setCurrentView('calculator')}
                    className={`px-4 py-1.5 rounded-lg text-[10px] font-black uppercase tracking-wider transition-all flex items-center gap-2 ${currentView === 'calculator' ? 'bg-white text-indigo-600 shadow-md shadow-slate-200' : 'text-slate-500 hover:text-slate-700'}`}
                  >
                    <LayoutGrid size={12} /> Skaičiuoklė
                  </button>
                  <button 
                    onClick={() => setCurrentView('stats')}
                    className={`px-4 py-1.5 rounded-lg text-[10px] font-black uppercase tracking-wider transition-all flex items-center gap-2 ${currentView === 'stats' ? 'bg-white text-indigo-600 shadow-md shadow-slate-200' : 'text-slate-500 hover:text-slate-700'}`}
                  >
                    <TrendingUp size={12} /> Statistika
                  </button>
               </nav>
            </div>
          </div>
        </div>
        <div className="flex gap-4">
          <button onClick={handleAudioGuide} disabled={isGeneratingAudio} className={`group relative flex items-center gap-2 px-6 py-3 rounded-2xl transition-all font-bold text-sm overflow-hidden ${isPlayingAudio ? 'bg-red-50 text-red-600 border border-red-100 shadow-red-50' : 'bg-white text-slate-600 border border-slate-200 hover:border-indigo-200 hover:text-indigo-600'} ${isGeneratingAudio ? 'opacity-70 cursor-not-allowed' : ''}`}>
            {isGeneratingAudio ? <Loader2 size={18} className="animate-spin" /> : isPlayingAudio ? <StopCircle size={18} /> : <Volume2 size={18} />}
            <span className="hidden sm:inline">{isPlayingAudio ? 'Sustabdyti' : 'Garsinis gidas'}</span>
          </button>
          <button onClick={() => setIsSettingsOpen(true)} className="p-3.5 bg-white text-slate-500 border border-slate-200 rounded-2xl hover:border-indigo-200 hover:text-indigo-600 hover:bg-indigo-50/30 transition-all duration-300">
            <Settings size={20} />
          </button>
        </div>
      </header>

      <main className="max-w-7xl mx-auto">
        {currentView === 'calculator' ? (
          <div className="grid grid-cols-1 lg:grid-cols-12 gap-10 animate-in fade-in duration-500 slide-in-from-bottom-2">
            <section className="lg:col-span-5 space-y-8">
              <div className="bg-white p-10 rounded-[3rem] shadow-[0_20px_50px_rgba(0,0,0,0.03)] border border-slate-100 relative overflow-hidden">
                <div className="absolute top-0 right-0 w-32 h-32 bg-indigo-50/50 rounded-bl-full -mr-10 -mt-10"></div>
                <h2 className="text-xl font-black text-slate-800 mb-8 flex items-center gap-3">
                  <div className="p-2 bg-indigo-50 text-indigo-600 rounded-xl">
                    <Sparkles size={20} />
                  </div>
                  Naujas įrašas
                </h2>

                <div className="space-y-6">
                  <div className="space-y-2">
                    <label className="text-[10px] font-black text-slate-400 uppercase tracking-[0.1em] ml-1 flex justify-between items-center">
                      <span>Vardas, Pavardė</span>
                      {suggestedCoefficient && (
                        <div className="flex items-center gap-1.5 text-indigo-500 lowercase bg-indigo-50/50 px-2 py-0.5 rounded-full border border-indigo-100">
                          <History size={10}/> istorija rasta
                        </div>
                      )}
                    </label>
                    <div className="group relative">
                      <div className="absolute inset-y-0 left-0 pl-4 flex items-center pointer-events-none">
                        <User className="text-slate-300 group-focus-within:text-indigo-500 transition-colors" size={18} />
                      </div>
                      <input 
                        type="text" 
                        list="names-list" 
                        value={fullName} 
                        onChange={e => handleInputChange(setFullName, 'fullName', e.target.value)} 
                        placeholder="Pvz.: Jonas Jonaitis" 
                        className={`w-full pl-12 pr-4 py-4 bg-slate-50/50 border-2 rounded-[1.5rem] outline-none transition-all focus:bg-white ${errors.fullName ? 'border-red-100 focus:border-red-300 ring-red-50' : 'border-slate-50 focus:border-indigo-100 focus:ring-4 focus:ring-indigo-50/30'}`} 
                      />
                      <datalist id="names-list">{historyData.names.map(n => <option key={n} value={n} />)}</datalist>
                    </div>
                    {errors.fullName && <p className="text-[10px] text-red-500 font-bold uppercase ml-2 mt-1">{errors.fullName}</p>}
                  </div>

                  <div className="space-y-2">
                    <label className="text-[10px] font-black text-slate-400 uppercase tracking-[0.1em] ml-1">Pareigos</label>
                    <div className="group relative">
                      <div className="absolute inset-y-0 left-0 pl-4 flex items-center pointer-events-none">
                        <Briefcase className="text-slate-300 group-focus-within:text-indigo-500 transition-colors" size={18} />
                      </div>
                      <input 
                        type="text" 
                        list="positions-list" 
                        value={position} 
                        onChange={e => handleInputChange(setPosition, 'position', e.target.value)} 
                        placeholder="Pvz.: Mokytojas metodininkas" 
                        className={`w-full pl-12 pr-4 py-4 bg-slate-50/50 border-2 rounded-[1.5rem] outline-none transition-all focus:bg-white ${errors.position ? 'border-red-100 focus:border-red-300 ring-red-50' : 'border-slate-50 focus:border-indigo-100 focus:ring-4 focus:ring-indigo-50/30'}`} 
                      />
                      <datalist id="positions-list">{historyData.positions.map(p => <option key={p} value={p} />)}</datalist>
                    </div>
                    {errors.position && <p className="text-[10px] text-red-500 font-bold uppercase ml-2 mt-1">{errors.position}</p>}
                  </div>

                  <div className="space-y-2">
                    <label className="text-[10px] font-black text-slate-400 uppercase tracking-[0.1em] ml-1">Savaitės darbo norma</label>
                    <div className="grid grid-cols-2 gap-4 p-1 bg-slate-50 rounded-2xl border border-slate-100">
                      {[WorkloadType.H36, WorkloadType.H40].map(t => (
                        <button 
                          key={t} 
                          onClick={() => setWorkloadType(t)} 
                          className={`py-3 rounded-xl font-black text-[10px] uppercase tracking-widest transition-all duration-300 ${workloadType === t ? 'bg-white text-indigo-600 shadow-sm border border-indigo-100' : 'text-slate-400 hover:text-slate-600 hover:bg-white/50'}`}
                        >
                          {t === WorkloadType.H36 ? '36 valandos' : '40 valandų'}
                        </button>
                      ))}
                    </div>
                  </div>

                  <div className="grid grid-cols-2 gap-5">
                    <div className="space-y-2">
                      <div className="flex justify-between items-end">
                        <label className="text-[10px] font-black text-slate-400 uppercase tracking-[0.1em] ml-1">Koeficientas</label>
                        {suggestedCoefficient && <button onClick={() => setBaseCoef(suggestedCoefficient.toString())} className="text-[9px] font-black text-indigo-600 bg-indigo-50 px-2 py-0.5 rounded-lg hover:bg-indigo-100 transition-all uppercase border border-indigo-100">Naudoti {suggestedCoefficient}</button>}
                      </div>
                      <input 
                        type="number" 
                        list="coefs-list" 
                        step="0.0001" 
                        value={baseCoef} 
                        onChange={e => setBaseCoef(e.target.value)} 
                        className="w-full px-5 py-4 bg-slate-50/50 border-2 border-slate-50 rounded-[1.5rem] font-mono font-black text-indigo-700 outline-none focus:bg-white focus:border-indigo-100 focus:ring-4 focus:ring-indigo-50/30 transition-all" 
                      />
                      <datalist id="coefs-list">{historyData.coefficients.map(c => <option key={c} value={c} />)}</datalist>
                    </div>
                    <div className="space-y-2">
                      <label className="text-[10px] font-black text-slate-400 uppercase tracking-[0.1em] ml-1">Fakt. valandos</label>
                      <div className="group relative">
                        <div className="absolute inset-y-0 left-0 pl-4 flex items-center pointer-events-none">
                          <Clock className="text-slate-300 group-focus-within:text-indigo-500 transition-colors" size={16} />
                        </div>
                        <input 
                          type="number" 
                          step="0.1" 
                          value={actualHours} 
                          onChange={e => handleInputChange(setActualHours, 'actualHours', e.target.value)} 
                          placeholder="0.0" 
                          className={`w-full pl-10 pr-4 py-4 bg-slate-50/50 border-2 rounded-[1.5rem] font-black outline-none transition-all focus:bg-white ${errors.actualHours ? 'border-red-100 focus:border-red-300 ring-red-50' : 'border-slate-50 focus:border-indigo-100 focus:ring-4 focus:ring-indigo-50/30'}`} 
                        />
                      </div>
                    </div>
                  </div>

                  <div className="space-y-2">
                    <label className="text-[10px] font-black text-slate-400 uppercase tracking-[0.1em] ml-1 flex items-center gap-2">
                      <CalendarDays size={14} className="text-indigo-400" /> Kiek dienų dirbo?
                    </label>
                    <input 
                      type="number" 
                      value={workedDays} 
                      onChange={e => handleInputChange(setWorkedDays, 'workedDays', e.target.value)} 
                      className={`w-full px-5 py-4 bg-slate-50/50 border-2 border-slate-50 rounded-[1.5rem] font-black outline-none focus:bg-white transition-all ${errors.workedDays ? 'border-red-100 focus:border-red-300 ring-red-50' : 'focus:border-indigo-100 focus:ring-4 focus:ring-indigo-50/30'}`} 
                    />
                    {errors.workedDays && <p className="text-[10px] text-red-500 font-bold uppercase ml-2 mt-1">{errors.workedDays}</p>}
                  </div>

                  <button 
                    onClick={handleSave} 
                    className="group w-full py-5 bg-gradient-to-tr from-indigo-700 via-indigo-600 to-indigo-500 text-white rounded-[1.5rem] font-black text-sm uppercase tracking-widest shadow-xl shadow-indigo-100 hover:shadow-indigo-200 hover:-translate-y-0.5 transition-all transform active:scale-[0.98] flex items-center justify-center gap-3"
                  >
                    <Save size={20} className="group-hover:rotate-12 transition-transform" /> Išsaugoti skaičiavimą
                  </button>
                </div>
              </div>

              <div className="bg-gradient-to-br from-slate-800 to-slate-900 p-8 rounded-[3rem] text-white shadow-2xl relative overflow-hidden group">
                 <div className="absolute top-0 right-0 w-48 h-48 bg-white/5 rounded-full -mr-16 -mt-16 blur-2xl group-hover:scale-110 transition-transform duration-700"></div>
                 <h3 className="text-xs font-black text-white/40 uppercase tracking-[0.2em] mb-6 flex items-center gap-3">
                    <BookMarked size={14} className="text-indigo-400" /> Naudingos nuorodos
                 </h3>
                 <div className="grid grid-cols-1 gap-3">
                    {[
                      { label: 'Bazinio dydžio įstatymas', url: 'https://www.e-tar.lt/portal/lt/legalAct/8253c29006c711ee9978886e85107ab2/asr' },
                      { label: 'Socialiniai rodikliai („Sodra“)', url: 'https://sodra.lt/statistika/pagrindiniai-socialiniai-rodikliai' },
                      { label: 'Metiniai laiko vidurkiai', url: 'https://www.tagidas.lt/savadai/9002/' }
                    ].map((link, idx) => (
                      <a key={idx} href={link.url} target="_blank" rel="noopener noreferrer" className="flex items-center justify-between p-4 bg-white/5 rounded-[1.25rem] hover:bg-white/10 transition-all border border-white/5 group/link">
                         <span className="text-xs font-bold text-slate-300 group-hover/link:text-white transition-colors">{link.label}</span>
                         <div className="p-1.5 bg-white/5 rounded-lg">
                           <ExternalLink size={14} className="text-indigo-400 group-hover/link:translate-x-0.5 group-hover/link:-translate-y-0.5 transition-transform" />
                         </div>
                      </a>
                    ))}
                 </div>
              </div>
            </section>

            <section className="lg:col-span-7 space-y-10">
              <div className="grid grid-cols-1 md:grid-cols-2 gap-8">
                <div className="bg-white p-10 rounded-[3rem] border border-slate-100 shadow-[0_15px_40px_rgba(0,0,0,0.02)] relative group overflow-hidden">
                  <div className="absolute top-0 right-0 w-24 h-24 bg-orange-50 rounded-bl-full opacity-50 group-hover:scale-110 transition-transform"></div>
                  <span className="text-[10px] font-black uppercase text-orange-400 block mb-3 tracking-[0.2em]">Paskaičiuota priemoka</span>
                  <div className="flex items-baseline gap-2">
                    <span className="text-5xl font-black text-slate-900">{formatCurrency(supplement).split(',')[0]}</span>
                    <span className="text-xl font-bold text-slate-400">,{formatCurrency(supplement).split(',')[1]}</span>
                  </div>
                </div>
                <div className="bg-white p-10 rounded-[3rem] border border-slate-100 shadow-[0_15px_40px_rgba(0,0,0,0.02)] relative group overflow-hidden">
                  <div className="absolute top-0 right-0 w-24 h-24 bg-cyan-50 rounded-bl-full opacity-50 group-hover:scale-110 transition-transform"></div>
                  <span className="text-[10px] font-black uppercase text-cyan-500 block mb-3 tracking-[0.2em]">Vid. etato dalis/d.</span>
                  <span className="text-5xl font-black text-slate-900">{formatNumber(dailyFte, 2)}</span>
                </div>
              </div>

              <div className="bg-white rounded-[3rem] shadow-[0_25px_60px_rgba(0,0,0,0.03)] border border-slate-100 overflow-hidden">
                <div className="p-8 border-b border-slate-50 flex flex-wrap justify-between items-center gap-4">
                  <div className="flex items-center gap-3">
                    <div className="p-2.5 bg-indigo-50 text-indigo-600 rounded-xl">
                      <Table size={20} />
                    </div>
                    <h3 className="text-lg font-black text-slate-800">Istorijos žurnalas</h3>
                  </div>
                  <div className="flex items-center gap-3">
                    {entries.length > 0 && (
                      <button 
                        onClick={() => setIsClearAllModalOpen(true)}
                        className="flex items-center gap-2 text-[10px] font-black uppercase tracking-widest text-red-500 bg-red-50/50 px-5 py-2.5 rounded-xl border border-red-100 hover:bg-red-500 hover:text-white transition-all duration-300"
                      >
                        <Eraser size={14} /> Išvalyti
                      </button>
                    )}
                    <button onClick={handleExportCsv} className="flex items-center gap-2 text-[10px] font-black uppercase tracking-widest text-indigo-600 bg-indigo-50 px-5 py-2.5 rounded-xl border border-indigo-100 hover:bg-indigo-600 hover:text-white shadow-sm transition-all duration-300">
                      <Download size={14} /> Eksportuoti
                    </button>
                  </div>
                </div>
                <div className="overflow-x-auto">
                  <table className="w-full text-left">
                    <thead className="bg-slate-50/30 text-[10px] font-black text-slate-400 uppercase tracking-[0.15em]">
                      <tr>
                        <th className="pl-10 pr-6 py-5">Darbuotojas</th>
                        <th className="px-6 py-5 text-center">Koef.</th>
                        <th className="px-6 py-5 text-center">Valandos</th>
                        <th className="px-6 py-5 text-center">Etatas</th>
                        <th className="px-6 py-5 text-right">Suma</th>
                        <th className="pl-6 pr-10 py-5"></th>
                      </tr>
                    </thead>
                    <tbody className="divide-y divide-slate-50">
                      {filteredEntries.map(e => (
                        <tr key={e.id} className="hover:bg-indigo-50/20 transition-all group">
                          <td className="pl-10 pr-6 py-6">
                            <div className="text-sm font-black text-slate-800 mb-0.5 group-hover:text-indigo-700 transition-colors">{e.fullName}</div>
                            <div className="text-[10px] font-bold text-slate-400 uppercase tracking-widest flex items-center gap-2">
                              {e.position}
                              <span className="w-1 h-1 rounded-full bg-slate-200"></span>
                              <span className="text-[9px] lowercase">{e.workloadType === WorkloadType.H36 ? '36 val.' : '40 val.'}</span>
                            </div>
                          </td>
                          <td className="px-6 py-6 text-center">
                            <span className="text-xs font-mono font-black text-slate-600 bg-slate-50 px-2 py-1 rounded-lg border border-slate-100">{formatNumber(e.finalCoefficient, 4)}</span>
                          </td>
                          <td className="px-6 py-6 text-center">
                            <div className="text-xs font-black text-slate-700">{e.actualHours} <span className="text-[9px] font-bold uppercase text-slate-400">val.</span></div>
                            <div className="text-[9px] font-bold text-slate-400 uppercase tracking-tighter">{e.workedDays} dienos</div>
                          </td>
                          <td className="px-6 py-6 text-center">
                            <span className="text-xs font-black text-cyan-600 bg-cyan-50 px-3 py-1.5 rounded-full border border-cyan-100">{formatNumber(e.dailyFte, 2)}</span>
                          </td>
                          <td className="px-6 py-6 text-right">
                            <span className="bg-gradient-to-tr from-indigo-50 to-indigo-100/50 text-indigo-700 px-4 py-2 rounded-2xl font-black text-sm border border-indigo-100 group-hover:from-indigo-600 group-hover:to-indigo-500 group-hover:text-white transition-all duration-500 shadow-sm group-hover:shadow-indigo-200">
                              {formatCurrency(e.salarySupplement)}
                            </span>
                          </td>
                          <td className="pl-6 pr-10 py-6 text-right">
                            <button onClick={() => setDeleteId(e.id)} className="p-2.5 text-slate-300 hover:text-red-500 hover:bg-red-50 rounded-xl transition-all">
                              <Trash2 size={16}/>
                            </button>
                          </td>
                        </tr>
                      ))}
                      {filteredEntries.length === 0 && (
                        <tr>
                          <td colSpan={6} className="px-10 py-24 text-center">
                            <div className="flex flex-col items-center gap-4 text-slate-300">
                              <div className="p-6 bg-slate-50 rounded-full">
                                <FileText size={48} strokeWidth={1} />
                              </div>
                              <p className="font-bold text-slate-400 uppercase tracking-widest text-xs italic">Istorija dar tuščia</p>
                            </div>
                          </td>
                        </tr>
                      )}
                    </tbody>
                  </table>
                </div>
              </div>
            </section>
          </div>
        ) : (
          <StatisticsView entries={entries} />
        )}
      </main>

      <footer className="max-w-7xl mx-auto mt-20 pt-10 border-t border-slate-100 flex flex-col sm:flex-row justify-between items-center gap-4 mb-12">
        <p className="text-[10px] font-black text-slate-400 uppercase tracking-[0.2em]">&copy; 2026 Priemokų skaičiuoklė. Visi teisės aktai aktualūs.</p>
        <div className="flex items-center gap-6">
           <a href="#" className="text-[10px] font-black text-slate-400 uppercase tracking-widest hover:text-indigo-600 transition-colors">Apie įrankį</a>
           <a href="#" className="text-[10px] font-black text-slate-400 uppercase tracking-widest hover:text-indigo-600 transition-colors">Privatumas</a>
        </div>
      </footer>

      <SettingsModal 
        isOpen={isSettingsOpen} 
        onClose={() => setIsSettingsOpen(false)} 
        config={config} 
        onSave={setConfig} 
        onTriggerClearAll={() => setIsClearAllModalOpen(true)}
      />
      <DeleteConfirmationModal isOpen={!!deleteId} onClose={() => setDeleteId(null)} onConfirm={confirmDelete} />
      <ClearAllConfirmationModal 
        isOpen={isClearAllModalOpen} 
        onClose={() => setIsClearAllModalOpen(false)} 
        onConfirm={handleClearAll} 
      />
    </div>
  );
};

export default App;
